#[test]
fn r34c_garnish_before_trailing_punctuation_is_judged_in_both_forms() {
    // RT34-5: a disagreeing garnish followed by ";",
    // ":", "!", "?", or a quote was judged in
    // NEITHER form — the trailing-word machinery's
    // trim set stopped before these marks, although
    // `weekday_word` honors ";" and ":" as boundary
    // endings elsewhere in the same parser. Both
    // forms now record the mismatch; the agreeing
    // garnish in each shape reads the date clean.
    for mark in [';', ':', '!', '?', '"'] {
        let glued_disagree = format!("November 1, 2026(Monday){mark}");
        let spaced_disagree = format!("November 1, 2026 (Monday){mark}");
        r34c_for_twin(
            &glued_disagree,
            &spaced_disagree,
            None,
            Some(("Monday", nov(1))),
        );
        let glued_agree = format!("November 1, 2026(Sunday){mark}");
        let spaced_agree = format!("November 1, 2026 (Sunday){mark}");
        r34c_for_twin(&glued_agree, &spaced_agree, Some(nov(1)), None);
        let glued_keep_disagree = format!("November 8, 2026(Monday){mark}");
        let spaced_keep_disagree = format!("November 8, 2026 (Monday){mark}");
        r34c_keep_twin(
            &glued_keep_disagree,
            &spaced_keep_disagree,
            None,
            Some(("Monday", nov(8))),
        );
        let glued_keep_agree = format!("November 8, 2026(Sunday){mark}");
        let spaced_keep_agree = format!("November 8, 2026 (Sunday){mark}");
        r34c_keep_twin(&glued_keep_agree, &spaced_keep_agree, Some(nov(8)), None);
    }
}

#[test]
fn r34c_non_garnish_glued_groups_keep_their_readings() {
    // The gate's invariants: every non-garnish glued
    // group keeps its text and reading byte-for-byte
    // — a group holding anything but one weekday
    // word is never re-spaced, in the plain shape or
    // in the new shapes the gate now sees past.
    for inner in [
        "notes",
        "November",
        "next week",
        "Monday morning",
        "2027",
        "Sundae",
        "Mondays",
    ] {
        let glued = format!("November 1, 2026({inner})");
        let spaced = format!("November 1, 2026 ({inner})");
        r34c_for_twin(&glued, &spaced, Some(nov(1)), None);
        let glued_extra = format!("November 1, 2026({inner}))");
        let spaced_extra = format!("November 1, 2026 ({inner}))");
        r34c_for_twin(&glued_extra, &spaced_extra, Some(nov(1)), None);
        let glued_doubled = format!("November 1, 2026(({inner}))");
        let spaced_doubled = format!("November 1, 2026 (({inner}))");
        r34c_for_twin(&glued_doubled, &spaced_doubled, Some(nov(1)), None);
        let glued_sep = format!("November 1, 2026({inner}) *");
        let spaced_sep = format!("November 1, 2026 ({inner}) *");
        r34c_for_twin(&glued_sep, &spaced_sep, Some(nov(1)), None);
    }
    // A glued parenthesized DATE is not a garnish:
    // it keeps its standing reading — the line's own
    // date stands and the parenthesized date is
    // recorded as disagreeing with it, glued exactly
    // as spaced.
    let glued_text = "For Sunday: November 1, 2026(November 8, 2026)\n\n## Announcement\n\nHi.\n";
    let g = parse_contribution(glued_text, today()).expect("parses");
    let spaced_text = "For Sunday: November 1, 2026 (November 8, 2026)\n\n## Announcement\n\nHi.\n";
    let s = parse_contribution(spaced_text, today()).expect("parses");
    assert_eq!(g.for_date, Some(nov(1)));
    assert_eq!(g.for_date, s.for_date);
    assert_eq!(g.named_weekday_mismatch, None);
    assert_eq!(
        g.for_sunday_parenthesized_mismatch, s.for_sunday_parenthesized_mismatch,
        "the glued parenthesized date records as its spaced twin"
    );
    assert!(g.for_sunday_parenthesized_mismatch.is_some());
}

// Round 34 (R34-E, F3): bracketed groups in
// contribution text are judged as their paren twins
// (coordinator's intent adjudication, audit-round34
// synthesis). The token machinery already assigns
// brackets the aside role — a bracketed token cleans
// to nothing at every token site, exactly as garnish
// does — so a bracket GROUP composes, strips, and
// cancels as the paren group with the same words:
// a cancelled bracket date cancels, a bracketed
// cancellation word leaves the core standing, a
// bracket group standing before the core is a group,
// and a glued bracket garnish is judged as its
// spaced twin. The pair types are the ones
// `is_bracketed_token` already treats as brackets:
// [] and {}. Every pin below asserts the bracket
// line's FULL record equals its paren twin's — the
// date, the second dates, both mismatch records and
// their review sentences, and the in-words memories.
// No paren reading moves: the paren side of every
// pair is the standing reading, pinned elsewhere.

fn r34e_for_twin(bracket: &str, paren: &str) {
    let bracket_text = format!("For Sunday: {bracket}\n\n## Announcement\n\nHi.\n");
    let b = parse_contribution(&bracket_text, today()).expect("parses");
    let paren_text = format!("For Sunday: {paren}\n\n## Announcement\n\nHi.\n");
    let p = parse_contribution(&paren_text, today()).expect("parses");
    assert_eq!(b.for_date, p.for_date, "{bracket}: the bracket twin's date");
    assert_eq!(
        b.named_weekday_mismatch, p.named_weekday_mismatch,
        "{bracket}: the bracket twin's weekday mismatch record"
    );
    if let (Some(bm), Some(pm)) = (&b.named_weekday_mismatch, &p.named_weekday_mismatch) {
        assert_eq!(
            bm.sentence(),
            pm.sentence(),
            "{bracket}: the review's weekday sentence is the twin's"
        );
    }
    assert_eq!(
        b.for_sunday_in_words, p.for_sunday_in_words,
        "{bracket}: the bracket twin's in-words memory"
    );
    assert_eq!(
        b.for_sunday_after_in_words, p.for_sunday_after_in_words,
        "{bracket}: the bracket twin's after-in-words memory"
    );
    assert_eq!(
        b.for_sunday_parenthesized_date, p.for_sunday_parenthesized_date,
        "{bracket}: the bracket twin's parenthesized date"
    );
    assert_eq!(
        b.for_sunday_parenthesized_dates, p.for_sunday_parenthesized_dates,
        "{bracket}: the bracket twin's parenthesized dates"
    );
    assert_eq!(
        b.for_sunday_parenthesized_mismatch, p.for_sunday_parenthesized_mismatch,
        "{bracket}: the bracket twin's parenthesized mismatch record"
    );
    if let (Some(bm), Some(pm)) = (
        &b.for_sunday_parenthesized_mismatch,
        &p.for_sunday_parenthesized_mismatch,
    ) {
        assert_eq!(
            bm.sentence(),
            pm.sentence(),
            "{bracket}: the review's parenthesized sentence is the twin's"
        );
    }
    assert_eq!(
        b.for_sunday_second_date, p.for_sunday_second_date,
        "{bracket}: the bracket twin's second date"
    );
    assert_eq!(
        b.for_sunday_second_dates, p.for_sunday_second_dates,
        "{bracket}: the bracket twin's second dates"
    );
}

fn r34e_keep_twin(bracket: &str, paren: &str) {
    let bracket_text = format!(
        "For Sunday: November 1, 2026\nKeep-through: {bracket}\n\n## Announcement\n\nHi.\n"
    );
    let b = parse_contribution(&bracket_text, today()).expect("parses");
    let paren_text =
        format!("For Sunday: November 1, 2026\nKeep-through: {paren}\n\n## Announcement\n\nHi.\n");
    let p = parse_contribution(&paren_text, today()).expect("parses");
    assert_eq!(
        b.for_date,
        Some(nov(1)),
        "{bracket}: the For Sunday line stands"
    );
    assert_eq!(
        p.for_date,
        Some(nov(1)),
        "{paren}: the For Sunday line stands"
    );
    assert_eq!(
        b.keep_through, p.keep_through,
        "{bracket}: the bracket twin's keep-through date"
    );
    assert_eq!(
        b.keep_through_weekday_mismatch, p.keep_through_weekday_mismatch,
        "{bracket}: the bracket twin's keep-through weekday record"
    );
    if let (Some(bm), Some(pm)) = (
        &b.keep_through_weekday_mismatch,
        &p.keep_through_weekday_mismatch,
    ) {
        assert_eq!(
            bm.keep_through_sentence(),
            pm.keep_through_sentence(),
            "{bracket}: the review's keep-through weekday sentence is the twin's"
        );
    }
    assert_eq!(
        b.keep_through_parenthesized_mismatch, p.keep_through_parenthesized_mismatch,
        "{bracket}: the bracket twin's keep-through parenthesized record"
    );
    if let (Some(bm), Some(pm)) = (
        &b.keep_through_parenthesized_mismatch,
        &p.keep_through_parenthesized_mismatch,
    ) {
        assert_eq!(
            bm.keep_through_sentence(),
            pm.keep_through_sentence(),
            "{bracket}: the review's keep-through sentence is the twin's"
        );
    }
    assert_eq!(
        b.keep_through_second_date, p.keep_through_second_date,
        "{bracket}: the bracket twin's keep-through second date"
    );
    assert_eq!(
        b.keep_through_second_dates, p.keep_through_second_dates,
        "{bracket}: the bracket twin's keep-through second dates"
    );
}

#[test]
fn r34e_cancelled_bracket_date_cancels_as_its_paren_twin() {
    // Family 1 of the adjudication: a cancelled date
    // inside a bracket group cancels exactly as it
    // does inside parens — it records nothing live.
    // (Witnessed before the fix: the bracket date
    // stood as a live second date.)
    let cases = [
        (
            "November 1, 2026 [November 8, 2026, cancelled]",
            "November 1, 2026 (November 8, 2026, cancelled)",
        ),
        (
            "November 1, 2026 [November 8, 2026, canceled]",
            "November 1, 2026 (November 8, 2026, canceled)",
        ),
        (
            "November 1, 2026 [November 8, 2026, postponed]",
            "November 1, 2026 (November 8, 2026, postponed)",
        ),
        (
            "November 1, 2026 [November 8, 2026 cancelled]",
            "November 1, 2026 (November 8, 2026 cancelled)",
        ),
        (
            "November 1, 2026 [[November 8, 2026, cancelled]]",
            "November 1, 2026 ((November 8, 2026, cancelled))",
        ),
        (
            "November 1, 2026 {November 8, 2026, cancelled}",
            "November 1, 2026 (November 8, 2026, cancelled)",
        ),
        // A cancelled bracket date standing BEFORE
        // the core is a group too: it names nothing.
        (
            "[November 8, 2026, cancelled] November 1, 2026",
            "(November 8, 2026, cancelled) November 1, 2026",
        ),
        // Two cancelled dates in one bracket group:
        // the paren reading splits its range — the
        // cancelled date records the standing
        // parenthesized mismatch, the rest stands —
        // and the bracket group inherits that reading
        // as-is (the adjudication's scope ruling).
        (
            "November 1, 2026 [November 8, 2026, November 15, 2026, cancelled]",
            "November 1, 2026 (November 8, 2026, November 15, 2026, cancelled)",
        ),
        (
            "November 1, 2026 [November 8, 2026 - November 15, 2026, cancelled]",
            "November 1, 2026 (November 8, 2026 - November 15, 2026, cancelled)",
        ),
    ];
    for (bracket, paren) in cases {
        r34e_for_twin(bracket, paren);
        r34e_keep_twin(
            &bracket.replace("November 1, 2026", "November 8, 2026"),
            &paren.replace("November 1, 2026", "November 8, 2026"),
        );
    }
    // The headline shape, stated outright: the core
    // stands and the cancelled bracket date records
    // nothing live anywhere.
    let text =
        "For Sunday: November 1, 2026 [November 8, 2026, cancelled]\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(1)));
    assert_eq!(c.for_sunday_second_dates, Vec::new());
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
    assert_eq!(c.for_sunday_parenthesized_dates, Vec::new());
    // The range twin's split, stated outright: the
    // cancelled date records the standing mismatch
    // and the rest of the range stands as a second
    // date — the bracket range records the SAME.
    let text = "For Sunday: November 1, 2026 [November 8, 2026 - November 15, 2026, cancelled]\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    let m = c
        .for_sunday_parenthesized_mismatch
        .as_ref()
        .expect("the cancelled range date records the standing mismatch");
    assert_eq!(m.named, nov(8));
    assert_eq!(c.for_sunday_second_dates, vec![nov(15)]);
}

#[test]
fn r34e_bracketed_cancellation_word_leaves_the_core_as_its_paren_twin() {
    // Family 2: a trailing bracket group is stripped
    // to form the core like a paren group, so a
    // bracketed aside of the pragmatic shape below
    // leaves the core date standing exactly as its
    // paren twin leaves it. (Witnessed before the
    // round-34 fix: the core read nothing at all.)
    // Round 39 (R39-H, F10) RESTATES the pure
    // governor arms of this family outright, flagged
    // in the batch record: a trailing group whose
    // whole contents are a governor phrase —
    // "[cancelled]", "[called off]", "{cancelled}" —
    // no longer leaves the core standing in either
    // dress; it governs as the bare governor governs,
    // so the twins below still compare equal (both
    // dresses moved together) and the headline
    // outright statement now reads None. The arms
    // holding more than a governor phrase (a date
    // beside the word, a relative phrase beside it)
    // and the inert asides are unmoved: their
    // standing readers judge them whole, in both
    // dresses alike.
    let cases = [
        (
            "November 1, 2026 [cancelled]",
            "November 1, 2026 (cancelled)",
        ),
        (
            "November 1, 2026 [called off]",
            "November 1, 2026 (called off)",
        ),
        (
            "November 1, 2026 [next Sunday, cancelled]",
            "November 1, 2026 (next Sunday, cancelled)",
        ),
        // The self case: the bracket group restates
        // the core's own date under a cancellation —
        // the paren twin keeps the core.
        (
            "November 1, 2026 [November 1, 2026, cancelled]",
            "November 1, 2026 (November 1, 2026, cancelled)",
        ),
        // The cancellation word standing first in
        // the group must not promote the date after
        // it to the headline.
        (
            "November 1, 2026 [cancelled, November 8, 2026]",
            "November 1, 2026 (cancelled, November 8, 2026)",
        ),
        // The whole line is the bracket group: it
        // reads exactly as the whole-line paren
        // group reads (nothing — its date is
        // cancelled).
        (
            "[November 1, 2026, cancelled]",
            "(November 1, 2026, cancelled)",
        ),
        (
            "November 1, 2026 {cancelled}",
            "November 1, 2026 (cancelled)",
        ),
        // The discriminators: a trailing bracket
        // group of any words is stripped to form the
        // core like a paren group, so these keep the
        // core exactly as (choir) / (foo bar) do.
        ("November 1, 2026 [choir]", "November 1, 2026 (choir)"),
        ("November 1, 2026 [foo bar]", "November 1, 2026 (foo bar)"),
        // A live bracketed date composes as its
        // paren twin too (control: no cancellation
        // anywhere in the group).
        (
            "November 1, 2026 [November 8, 2026]",
            "November 1, 2026 (November 8, 2026)",
        ),
    ];
    for (bracket, paren) in cases {
        r34e_for_twin(bracket, paren);
    }
    r34e_keep_twin(
        "November 8, 2026 [cancelled]",
        "November 8, 2026 (cancelled)",
    );
    r34e_keep_twin("November 8, 2026 [choir]", "November 8, 2026 (choir)");
    // The headline shapes, stated outright. The
    // pure governor headline is RESTATED by R39-H
    // (see the family note above): the bracketed
    // cancellation governs, as its paren twin and
    // its bare twin govern — no date reads.
    let text = "For Sunday: November 1, 2026 [cancelled]\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(
        c.for_date, None,
        "the trailing bracketed governor governs (R39-H)"
    );
    assert_eq!(c.for_sunday_second_dates, Vec::new());
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
    let text =
        "For Sunday: November 1, 2026 [cancelled, November 8, 2026]\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(
        c.for_date,
        Some(nov(1)),
        "the cancelled group's date is not the headline"
    );
}

#[test]
fn r34e_nested_bracket_groups_compose_as_their_paren_twins() {
    // Family 3: nesting. A paren group inside a
    // bracket group composes clean like its twin
    // with the pairs swapped (which already composes
    // clean), and a bracket group nested inside a
    // bracket group reads as the paren nesting does.
    r34e_for_twin(
        "November 1, 2026 [(November 8, 2026), cancelled]",
        "November 1, 2026 ([November 8, 2026], cancelled)",
    );
    // Scope note, on the record: one shape of the
    // red team's 35 was NOT a twin under the
    // round-34 inner rules and is not pinned here —
    // a cancellation word wearing brackets INSIDE a
    // group inner ("[November 8, 2026 [cancelled]]").
    // Inside a group, a wholly bracketed token kept
    // its round-24 garnish role and was no word at
    // all (r25a's held line: "(November 1 [choir])"
    // stays governed where "(November 1 choir)"
    // asserts), so the bracketed word did not
    // govern there, while the unwrapped paren word
    // did. The adjudication made the bracket pair
    // a group delimiter; it did not rewrite the
    // inner token rules it cited as its premise.
    // Carried to round 35 with the mixed closers
    // (which close nothing under the stack walk and
    // keep their round-34 readings byte for byte).
    // Round 35 (R35-B, F2) supersedes the carried
    // shape: a governing word now governs however
    // it is wrapped inside a group inner, while
    // garnish words keep the round-24 rule — the
    // cross-cell battery is pinned in
    // `r35b_bracketed_governing_word_governs_as_its_paren_twin`.
    let text =
        "For Sunday: November 1, 2026 [(November 8, 2026), cancelled]\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(
        c.for_date,
        Some(nov(1)),
        "the cancelled date is not the Sunday"
    );
    assert_eq!(c.for_sunday_second_dates, Vec::new());
}

#[test]
fn r34e_bracket_groups_beside_a_plain_core_read_as_their_paren_twins() {
    // A bracket group standing before or after a
    // plain core composes exactly as the paren
    // group does: the core reads, and the group's
    // disagreeing date is recorded on the
    // parenthesized record, not named as a plain
    // second date. (These are the round-24 M5
    // shapes, whose bracket readings the
    // adjudication supersedes; the flips are
    // flagged in `r24a_boundary_token_rule`.)
    r34e_for_twin(
        "[November 8, 2026], November 15, 2026",
        "(November 8, 2026), November 15, 2026",
    );
    r34e_for_twin(
        "{November 8, 2026}, November 15, 2026",
        "(November 8, 2026), November 15, 2026",
    );
    r34e_for_twin(
        "November 15, 2026, [November 8, 2026]",
        "November 15, 2026, (November 8, 2026)",
    );
    r34e_for_twin(
        "cancelled [November 8, 2026]",
        "cancelled (November 8, 2026)",
    );
    r34e_for_twin(
        "Sunday bulletins, [November 8, 2026]",
        "Sunday bulletins, (November 8, 2026)",
    );
    // A bracketed date standing alone on the line
    // is a line of one group, read as the paren
    // group is read (the round-24/25 alone-unread
    // limitation is superseded by the adjudication;
    // the flips are flagged in place).
    r34e_for_twin("[November 8]", "(November 8)");
    r34e_for_twin("[choir November 1]", "(choir November 1)");
}

#[test]
fn r34e_glued_bracket_garnish_reads_as_its_spaced_and_paren_twins() {
    // Family 4 (RT34-2's bracket pairs): a glued
    // bracket garnish is judged exactly as its
    // spaced twin and as the paren garnish — a
    // disagreeing weekday records the mismatch, an
    // agreeing one reads the date clean. (Witnessed
    // before the fix: both glued forms yielded no
    // date and no record at all.)
    r34e_for_twin("November 1, 2026[Monday]", "November 1, 2026 [Monday]");
    r34e_for_twin("November 1, 2026[Monday]", "November 1, 2026(Monday)");
    r34e_for_twin("November 1, 2026[Sunday]", "November 1, 2026 [Sunday]");
    r34e_for_twin("November 1, 2026[Sunday]", "November 1, 2026(Sunday)");
    // Round 35 (R35-A, F1 = review R35-R1): the
    // brace lines below were corrected — as first
    // written they compared the glued brace garnish
    // only against its spaced brace twin, the two
    // unjudged forms agreeing with each other while
    // both diverged from the paren twin this test's
    // name claims. The brace forms now compare
    // against the paren twins, glued and spaced,
    // agreeing and disagreeing, on both lines; the
    // full brace family across the R34-C suffix
    // layers is pinned in
    // `r35a_brace_weekday_garnish_is_judged_as_its_paren_twin`.
    r34e_for_twin("November 1, 2026{Monday}", "November 1, 2026(Monday)");
    r34e_for_twin("November 1, 2026 {Monday}", "November 1, 2026 (Monday)");
    r34e_for_twin("November 1, 2026{Sunday}", "November 1, 2026(Sunday)");
    r34e_for_twin("November 1, 2026 {Sunday}", "November 1, 2026 (Sunday)");
    r34e_keep_twin("November 8, 2026[Monday]", "November 8, 2026 [Monday]");
    r34e_keep_twin("November 8, 2026[Monday]", "November 8, 2026(Monday)");
    r34e_keep_twin("November 8, 2026{Monday}", "November 8, 2026(Monday)");
    r34e_keep_twin("November 8, 2026 {Monday}", "November 8, 2026 (Monday)");
    r34e_keep_twin("November 8, 2026{Sunday}", "November 8, 2026(Sunday)");
    // Stated outright: the disagreeing glued garnish
    // records the mismatch; the agreeing one reads
    // the date clean.
    let text = "For Sunday: November 1, 2026[Monday]\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing glued bracket weekday is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text = "For Sunday: November 1, 2026[Sunday]\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(1)));
    assert_eq!(c.named_weekday_mismatch, None);
}

#[test]
fn r35a_brace_weekday_garnish_is_judged_as_its_paren_twin() {
    // Round 35 (R35-A, F1 = review R35-R1): a weekday
    // garnish in braces was never judged — the weekday
    // readers' own trim sets stopped before "{" and
    // "}", so "{Monday}" never cleaned to the word it
    // names and the group machinery stripped the brace
    // group as anonymous garnish: a disagreeing weekday
    // in braces left the date standing in silence,
    // where its paren and bracket twins refuse the date
    // and record the mismatch. Witnessed spaced, glued,
    // extra-close, doubled, punctuated, and leading, on
    // the For line and the Keep-through line. The brace
    // family is pinned here across the R34-C suffix
    // layers, each brace form against its paren twin
    // with the full record compared, agreeing and
    // disagreeing, on both lines. November 1 and
    // November 8, 2026 are Sundays: "Monday" disagrees,
    // "Sunday" agrees.
    let for_pairs = [
        // The plain forms, spaced and glued.
        ("November 1, 2026 {Monday}", "November 1, 2026 (Monday)"),
        ("November 1, 2026{Monday}", "November 1, 2026(Monday)"),
        ("November 1, 2026 {Sunday}", "November 1, 2026 (Sunday)"),
        ("November 1, 2026{Sunday}", "November 1, 2026(Sunday)"),
        // Extra closing marks: the witnessed stray ")"
        // after the brace group, and the pair's own
        // extra "}".
        ("November 1, 2026{Monday})", "November 1, 2026(Monday))"),
        ("November 1, 2026 {Monday})", "November 1, 2026 (Monday))"),
        ("November 1, 2026{Monday}}", "November 1, 2026(Monday))"),
        ("November 1, 2026 {Monday}}", "November 1, 2026 (Monday))"),
        ("November 1, 2026{Sunday}}", "November 1, 2026(Sunday))"),
        // A doubled garnish, glued and spaced.
        ("November 1, 2026{{Monday}}", "November 1, 2026((Monday))"),
        ("November 1, 2026 {{Monday}}", "November 1, 2026 ((Monday))"),
        ("November 1, 2026{{Sunday}}", "November 1, 2026((Sunday))"),
        // The leading slot, spaced. (A glued leading
        // group is round 35's F3, batch R35-C — not
        // this batch's shape.)
        ("{Monday} November 1, 2026", "(Monday) November 1, 2026"),
        ("{Sunday} November 1, 2026", "(Sunday) November 1, 2026"),
        // The Sunday-after reader this batch's fix
        // also touches: a braced garnish on the base
        // date, judged against the base as its paren
        // twin is.
        (
            "Sunday after November 1, 2026 {Monday}",
            "Sunday after November 1, 2026 (Monday)",
        ),
        (
            "Sunday after November 1, 2026 {Sunday}",
            "Sunday after November 1, 2026 (Sunday)",
        ),
    ];
    for (brace, paren) in for_pairs {
        r34e_for_twin(brace, paren);
    }
    let keep_pairs = [
        ("November 8, 2026 {Monday}", "November 8, 2026 (Monday)"),
        ("November 8, 2026{Monday}", "November 8, 2026(Monday)"),
        ("November 8, 2026 {Sunday}", "November 8, 2026 (Sunday)"),
        ("November 8, 2026{Sunday}", "November 8, 2026(Sunday)"),
        ("November 8, 2026{Monday})", "November 8, 2026(Monday))"),
        ("November 8, 2026{Monday}}", "November 8, 2026(Monday))"),
        ("November 8, 2026{Sunday}}", "November 8, 2026(Sunday))"),
        ("November 8, 2026{{Monday}}", "November 8, 2026((Monday))"),
        ("November 8, 2026 {{Monday}}", "November 8, 2026 ((Monday))"),
        ("November 8, 2026{{Sunday}}", "November 8, 2026((Sunday))"),
        ("{Monday} November 8, 2026", "(Monday) November 8, 2026"),
        ("{Sunday} November 8, 2026", "(Sunday) November 8, 2026"),
    ];
    for (brace, paren) in keep_pairs {
        r34e_keep_twin(brace, paren);
    }
    // A trailing separator token after the garnish,
    // glued and spaced, agreeing and disagreeing.
    for sep in [" *", " |"] {
        let glued_disagree = format!("November 1, 2026{{Monday}}{sep}");
        let paren_disagree = format!("November 1, 2026(Monday){sep}");
        r34e_for_twin(&glued_disagree, &paren_disagree);
        let spaced_disagree = format!("November 1, 2026 {{Monday}}{sep}");
        let paren_spaced = format!("November 1, 2026 (Monday){sep}");
        r34e_for_twin(&spaced_disagree, &paren_spaced);
        let glued_agree = format!("November 1, 2026{{Sunday}}{sep}");
        let paren_agree = format!("November 1, 2026(Sunday){sep}");
        r34e_for_twin(&glued_agree, &paren_agree);
        let keep_disagree = format!("November 8, 2026{{Monday}}{sep}");
        let keep_paren = format!("November 8, 2026(Monday){sep}");
        r34e_keep_twin(&keep_disagree, &keep_paren);
        let keep_agree = format!("November 8, 2026{{Sunday}}{sep}");
        let keep_paren_agree = format!("November 8, 2026(Sunday){sep}");
        r34e_keep_twin(&keep_agree, &keep_paren_agree);
    }
    // Trailing punctuation after the garnish, glued
    // and spaced, agreeing and disagreeing — the
    // R34-C marks, judged for the brace pair as for
    // the paren pair.
    for mark in [';', ':', '!', '?', '"'] {
        let glued_disagree = format!("November 1, 2026{{Monday}}{mark}");
        let paren_disagree = format!("November 1, 2026(Monday){mark}");
        r34e_for_twin(&glued_disagree, &paren_disagree);
        let spaced_disagree = format!("November 1, 2026 {{Monday}}{mark}");
        let paren_spaced = format!("November 1, 2026 (Monday){mark}");
        r34e_for_twin(&spaced_disagree, &paren_spaced);
        let glued_agree = format!("November 1, 2026{{Sunday}}{mark}");
        let paren_agree = format!("November 1, 2026(Sunday){mark}");
        r34e_for_twin(&glued_agree, &paren_agree);
        let keep_disagree = format!("November 8, 2026{{Monday}}{mark}");
        let keep_paren = format!("November 8, 2026(Monday){mark}");
        r34e_keep_twin(&keep_disagree, &keep_paren);
        let keep_spaced = format!("November 8, 2026 {{Monday}}{mark}");
        let keep_paren_spaced = format!("November 8, 2026 (Monday){mark}");
        r34e_keep_twin(&keep_spaced, &keep_paren_spaced);
        let keep_agree = format!("November 8, 2026{{Sunday}}{mark}");
        let keep_paren_agree = format!("November 8, 2026(Sunday){mark}");
        r34e_keep_twin(&keep_agree, &keep_paren_agree);
    }
    // Stated outright, the witnessed disagreeing
    // forms: the date is refused and the mismatch is
    // recorded, exactly as the paren twin records it.
    let text = "For Sunday: November 1, 2026 {Monday}\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing brace weekday is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text = "For Sunday: November 1, 2026\nKeep-through: November 29, 2026 {Monday}\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, None);
    let m = c
        .keep_through_weekday_mismatch
        .as_ref()
        .expect("the disagreeing brace weekday on the keep line is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(29));
    // And the agreeing brace garnish reads clean.
    let text = "For Sunday: November 1, 2026 {Sunday}\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(1)));
    assert_eq!(c.named_weekday_mismatch, None);
}

#[test]
fn r35h_bracketed_weekday_naming_the_sunday_after_shape_consumes_its_base_as_its_paren_twin() {
    // Round 35 (R35-H; the scope note R35-A's pin
    // work recorded): R35-A made a braced weekday
    // clean to its word at the weekday readers, so
    // "{Sunday} after November 1, 2026" read its
    // date and its mismatch as its paren twin did —
    // but it still recorded the base, November 1,
    // as a second date where the paren twin records
    // none. The divergence lived in the second-date
    // machinery: the Sunday-after phrase scan
    // (`sunday_after_phrase_run`) reads its words
    // through the shared cleaning (`group_token`),
    // which reads a wholly bracketed token as
    // garnish and gives nothing for it, where the
    // paren twin's token cleans through its edges
    // to the word — so the scan never saw the
    // phrase, and the base stood as a plain date
    // run beside the resolution. The same failure
    // at the base's own leading weekday ran the
    // other way: "Sunday after {Monday} November 1,
    // 2026" recorded nothing where the paren twin
    // names the phrase's resolution, November 8,
    // as the second date beside the base the line
    // itself reads. The scan now asks the raw token
    // for its bracketed word (`bracketed_weekday_word`)
    // at both spots — the shape word and the base's
    // leading weekday, behind an optional "on" —
    // so a bracketed weekday names the shape
    // exactly as its paren twin does, and the
    // phrase consumes its base on every channel
    // the scan feeds. Witnessed before the fix on
    // both lines: the shape cells (plain, lead-in,
    // glued) carried the base as a second date; the
    // base-leading cells (agreeing, disagreeing,
    // "on"-framed) carried no second date; the
    // base-trailing cells already agreed and are
    // pinned in `r35a_brace_weekday_garnish_is_judged_as_its_paren_twin`.
    // November 1, 2026 is a Sunday; the Sunday
    // after it is November 8.
    let for_pairs = [
        // The shape word itself, spaced, with its
        // lead-ins, and glued (the date line's
        // re-spacing hands the scan the spaced
        // twin, as it does the paren form).
        (
            "{Sunday} after November 1, 2026",
            "(Sunday) after November 1, 2026",
        ),
        (
            "[Sunday] after November 1, 2026",
            "(Sunday) after November 1, 2026",
        ),
        (
            "the {Sunday} after November 1, 2026",
            "the (Sunday) after November 1, 2026",
        ),
        (
            "on the {Sunday} after November 1, 2026",
            "on the (Sunday) after November 1, 2026",
        ),
        (
            "words for {Sunday} after November 1, 2026 please",
            "words for (Sunday) after November 1, 2026 please",
        ),
        (
            "{Sunday}after November 1, 2026",
            "(Sunday)after November 1, 2026",
        ),
        (
            "[Sunday]after November 1, 2026",
            "(Sunday)after November 1, 2026",
        ),
        // The base's own leading weekday, agreeing
        // and disagreeing, bracketed and braced,
        // bare and behind "on".
        (
            "Sunday after {Sunday} November 1, 2026",
            "Sunday after (Sunday) November 1, 2026",
        ),
        (
            "Sunday after {Monday} November 1, 2026",
            "Sunday after (Monday) November 1, 2026",
        ),
        (
            "Sunday after [Monday] November 1, 2026",
            "Sunday after (Monday) November 1, 2026",
        ),
        (
            "Sunday after on {Monday} November 1, 2026",
            "Sunday after on (Monday) November 1, 2026",
        ),
        (
            "Sunday after on {Sunday} November 1, 2026",
            "Sunday after on (Sunday) November 1, 2026",
        ),
        // Both bracketed spots at once, and the
        // shape word standing in a plain core.
        (
            "{Sunday} after {Monday} November 1, 2026",
            "(Sunday) after (Monday) November 1, 2026",
        ),
        (
            "{Sunday} after {Sunday} November 1, 2026",
            "(Sunday) after (Sunday) November 1, 2026",
        ),
        (
            "{Sunday} after November 1, 2026 {Sunday}",
            "(Sunday) after November 1, 2026 (Sunday)",
        ),
        (
            "use {Sunday} after November 1, 2026",
            "use (Sunday) after November 1, 2026",
        ),
        (
            "use Sunday after {Monday} November 1, 2026",
            "use Sunday after (Monday) November 1, 2026",
        ),
        // The base restated, and a real second
        // date standing beside the phrase: the
        // restated base stays a restatement, and
        // November 15 is named for both twins.
        (
            "{Sunday} after November 1, 2026 (November 1, 2026)",
            "(Sunday) after November 1, 2026 (November 1, 2026)",
        ),
        (
            "{Sunday} after November 1, 2026 and November 15, 2026",
            "(Sunday) after November 1, 2026 and November 15, 2026",
        ),
    ];
    for (bracket, paren) in for_pairs {
        r34e_for_twin(bracket, paren);
    }
    let keep_pairs = [
        (
            "{Sunday} after November 1, 2026",
            "(Sunday) after November 1, 2026",
        ),
        (
            "[Sunday] after November 1, 2026",
            "(Sunday) after November 1, 2026",
        ),
        (
            "{Sunday}after November 1, 2026",
            "(Sunday)after November 1, 2026",
        ),
        (
            "Sunday after {Sunday} November 1, 2026",
            "Sunday after (Sunday) November 1, 2026",
        ),
        (
            "Sunday after {Monday} November 1, 2026",
            "Sunday after (Monday) November 1, 2026",
        ),
        (
            "Sunday after on {Monday} November 1, 2026",
            "Sunday after on (Monday) November 1, 2026",
        ),
        (
            "{Sunday} after {Monday} November 1, 2026",
            "(Sunday) after (Monday) November 1, 2026",
        ),
        (
            "{Sunday} after November 1, 2026 (November 1, 2026)",
            "(Sunday) after November 1, 2026 (November 1, 2026)",
        ),
        (
            "{Sunday} after November 1, 2026 and November 15, 2026",
            "(Sunday) after November 1, 2026 and November 15, 2026",
        ),
    ];
    for (bracket, paren) in keep_pairs {
        r34e_keep_twin(bracket, paren);
    }
    // Stated outright, the two witnessed directions.
    // The shape cell: the resolution reads and the
    // base is no second date, on either line.
    let text = "For Sunday: {Sunday} after November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    assert_eq!(c.for_sunday_second_date, None);
    assert_eq!(c.for_sunday_second_dates, Vec::<SimpleDate>::new());
    let text = "For Sunday: November 1, 2026\nKeep-through: {Sunday} after November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, Some(nov(8)));
    assert_eq!(c.keep_through_second_date, None);
    assert_eq!(c.keep_through_second_dates, Vec::<SimpleDate>::new());
    // The base-leading cell, as round 36 (R36-B,
    // F2) supersedes the reading first stated here:
    // the whole-line reader (`sunday_after_base`)
    // then judged the base's leading weekday through
    // a reader that never unwraps a pair, so the
    // wrapped form's phrase reading failed there and
    // the line fell to the generic reading — it read
    // its base, with the phrase's resolution named
    // as the second date beside it. That reader now
    // unwraps the leading weekday as its twins do,
    // so the wrapped disagreeing form is judged as
    // its bare twin is: no date reads, and the
    // mismatch is recorded. The pair comparisons
    // above stand unchanged (the twins still agree
    // field for field); the wrapped family is
    // pinned against the bare twin in
    // `r36b_wrapped_base_leading_weekday_is_judged_as_its_bare_twin`.
    let text = "For Sunday: Sunday after {Monday} November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing wrapped base-leading weekday is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    assert_eq!(c.for_sunday_second_date, None);
    assert_eq!(c.for_sunday_second_dates, Vec::<SimpleDate>::new());
}

#[test]
fn r36b_bracketed_sunday_after_shape_inside_a_group_consumes_its_base_as_its_paren_twin() {
    // Round 36 (R36-B, F3 = review R36-3 = red team
    // RT36-1 = verify target (b); the canary the
    // R35-H record's scope note flagged): inside a
    // group, the Sunday-after phrase is assembled
    // from `group_token`-cleaned tokens, and a
    // wholly bracketed shape word cleans to nothing,
    // so the phrase never formed in the group
    // analysis — its base stood as a plain signal,
    // and `mismatch_from_groups` recorded it against
    // the resolution: "November 15, 2026 ({Sunday}
    // after November 1, 2026)" recorded
    // ParenthesizedDateMismatch { named: November 1,
    // read: November 8 } with its "check the date
    // with the sender" sentence, on both routes,
    // under every outer wrapper, and on the fully
    // agreeing line too, where the paren and bare
    // twins record nothing. The proximate site was
    // the group-signals gate: `dates_inside_group_signals`
    // consulted the phrase run only when the CLEANED
    // token already equalled "sunday", so R35-H's
    // raw-token fix was unreachable there. The gate
    // now asks the raw token for its bracketed word,
    // as the phrase scan does; `group_token` itself
    // is unchanged. The both-braced form additionally
    // named the base in the record where its
    // paren-shape twin names the resolution — pinned
    // below in trailing and whole-line forms.
    // November 1, 2026 is a Sunday; the Sunday after
    // it is November 8. Every pair compares the full
    // record (the r34e helpers).
    let for_pairs = [
        // The canary and the agreeing line, inner
        // brace and bracket against the paren twin.
        (
            "November 15, 2026 ({Sunday} after November 1, 2026)",
            "November 15, 2026 ((Sunday) after November 1, 2026)",
        ),
        (
            "November 15, 2026 ([Sunday] after November 1, 2026)",
            "November 15, 2026 ((Sunday) after November 1, 2026)",
        ),
        (
            "November 8, 2026 ({Sunday} after November 1, 2026)",
            "November 8, 2026 ((Sunday) after November 1, 2026)",
        ),
        (
            "November 8, 2026 ([Sunday] after November 1, 2026)",
            "November 8, 2026 ((Sunday) after November 1, 2026)",
        ),
        // Every outer wrapper: the phantom followed
        // the inner wrap, not the outer one.
        (
            "November 15, 2026 [{Sunday} after November 1, 2026]",
            "November 15, 2026 [(Sunday) after November 1, 2026]",
        ),
        (
            "November 15, 2026 {{Sunday} after November 1, 2026}",
            "November 15, 2026 {(Sunday) after November 1, 2026}",
        ),
        (
            "November 15, 2026 (({Sunday} after November 1, 2026))",
            "November 15, 2026 (((Sunday) after November 1, 2026))",
        ),
        // The whole line is the group.
        (
            "({Sunday} after November 1, 2026)",
            "((Sunday) after November 1, 2026)",
        ),
        (
            "([Sunday] after November 1, 2026)",
            "((Sunday) after November 1, 2026)",
        ),
        // Both spots wrapped, trailing and whole-line,
        // against the paren-shape twin (whose base
        // weekday stands wrapped in turn) and against
        // the both-paren form: disagreeing, the line
        // is refused with the weekday mismatch the
        // bare form records; agreeing, the resolution
        // reads with the core as its second date.
        (
            "November 15, 2026 ({Sunday} after {Monday} November 1, 2026)",
            "November 15, 2026 (Sunday after {Monday} November 1, 2026)",
        ),
        (
            "November 15, 2026 ({Sunday} after {Monday} November 1, 2026)",
            "November 15, 2026 ((Sunday) after (Monday) November 1, 2026)",
        ),
        (
            "November 15, 2026 ({Sunday} after {Sunday} November 1, 2026)",
            "November 15, 2026 (Sunday after {Sunday} November 1, 2026)",
        ),
        (
            "({Sunday} after {Monday} November 1, 2026)",
            "(Sunday after {Monday} November 1, 2026)",
        ),
        (
            "({Sunday} after {Sunday} November 1, 2026)",
            "((Sunday) after (Sunday) November 1, 2026)",
        ),
    ];
    for (bracket, paren) in for_pairs {
        r34e_for_twin(bracket, paren);
    }
    let keep_pairs = [
        (
            "November 15, 2026 ({Sunday} after November 1, 2026)",
            "November 15, 2026 ((Sunday) after November 1, 2026)",
        ),
        (
            "November 8, 2026 ([Sunday] after November 1, 2026)",
            "November 8, 2026 ((Sunday) after November 1, 2026)",
        ),
        (
            "({Sunday} after November 1, 2026)",
            "((Sunday) after November 1, 2026)",
        ),
        (
            "November 15, 2026 ({Sunday} after {Monday} November 1, 2026)",
            "November 15, 2026 (Sunday after {Monday} November 1, 2026)",
        ),
        (
            "November 15, 2026 ({Sunday} after {Sunday} November 1, 2026)",
            "November 15, 2026 (Sunday after {Sunday} November 1, 2026)",
        ),
    ];
    for (bracket, paren) in keep_pairs {
        r34e_keep_twin(bracket, paren);
    }
    // Stated outright: the canary records nothing,
    // on either line — the resolution reads and the
    // core stands as the second date.
    let text = "For Sunday: November 15, 2026 ({Sunday} after November 1, 2026)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
    assert_eq!(c.for_sunday_second_dates, vec![nov(15)]);
    let text = "For Sunday: November 1, 2026\nKeep-through: November 15, 2026 ({Sunday} after November 1, 2026)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, Some(nov(8)));
    assert_eq!(c.keep_through_parenthesized_mismatch, None);
    assert_eq!(c.keep_through_second_dates, vec![nov(15)]);
    // The agreeing line records nothing either.
    let text = "For Sunday: November 8, 2026 ({Sunday} after November 1, 2026)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
}

#[test]
fn r36b_wrapped_base_leading_weekday_is_judged_as_its_bare_twin() {
    // Round 36 (R36-B, F2 = review R36-2):
    // `sunday_after_base` judged the base's leading
    // weekday through `weekday_word` on the raw
    // token, which never unwraps a bracket pair;
    // R35-H's `bracketed_weekday_word` reached the
    // phrase-scan sites, not this whole-line reader.
    // "Sunday after (Monday) November 1, 2026" (any
    // wrapper, doubled and mixed included) read
    // for = November 1 with the resolution demoted
    // to a second date and NO record, where the bare
    // twin refuses with the mismatch recorded; the
    // agreeing "(Sunday)" form collapsed the same
    // way (November 1, not November 8). The reader
    // now asks for the leading weekday as the phrase
    // scan asks — through the shared cleaning and
    // the raw token's bracketed word — bare or
    // behind "on". Every pair below compares the
    // wrapped line's full record against its BARE
    // twin's (the r34e helpers, whose second form is
    // the standing reading). November 1, 2026 is a
    // Sunday: "Monday" disagrees, "Sunday" agrees.
    let wrapped = [
        "(Monday)",
        "[Monday]",
        "{Monday}",
        "((Monday))",
        "[[Monday]]",
        "{{Monday}}",
        "([Monday])",
        "[(Monday)]",
        "{[Monday]}",
    ];
    for w in wrapped {
        let line = format!("Sunday after {w} November 1, 2026");
        r34e_for_twin(&line, "Sunday after Monday November 1, 2026");
    }
    let wrapped_agree = [
        "(Sunday)",
        "[Sunday]",
        "{Sunday}",
        "((Sunday))",
        "[[Sunday]]",
        "{{Sunday}}",
        "([Sunday])",
        "[(Sunday)]",
        "{[Sunday]}",
    ];
    for w in wrapped_agree {
        let line = format!("Sunday after {w} November 1, 2026");
        r34e_for_twin(&line, "Sunday after Sunday November 1, 2026");
    }
    for w in [
        "(Monday)",
        "[Monday]",
        "{Monday}",
        "[[Monday]]",
        "([Monday])",
    ] {
        let line = format!("Sunday after {w} November 1, 2026");
        r34e_keep_twin(&line, "Sunday after Monday November 1, 2026");
    }
    for w in [
        "(Sunday)",
        "[Sunday]",
        "{Sunday}",
        "[[Sunday]]",
        "([Sunday])",
    ] {
        let line = format!("Sunday after {w} November 1, 2026");
        r34e_keep_twin(&line, "Sunday after Sunday November 1, 2026");
    }
    // The behind-"on" controls: the disagreeing
    // forms judged correctly before this batch and
    // keep that outcome exactly; the agreeing forms
    // read as their bare twins.
    for w in ["(Monday)", "[Monday]", "{Monday}"] {
        let line = format!("Sunday after on {w} November 1, 2026");
        r34e_for_twin(&line, "Sunday after on Monday November 1, 2026");
        r34e_keep_twin(&line, "Sunday after on Monday November 1, 2026");
    }
    for w in ["(Sunday)", "[Sunday]", "{Sunday}"] {
        let line = format!("Sunday after on {w} November 1, 2026");
        r34e_for_twin(&line, "Sunday after on Sunday November 1, 2026");
        r34e_keep_twin(&line, "Sunday after on Sunday November 1, 2026");
    }
    // Stated outright: the disagreeing wrapped form
    // is refused with the mismatch recorded; the
    // agreeing wrapped form resolves to November 8
    // with no second date.
    let text = "For Sunday: Sunday after (Monday) November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing wrapped base-leading weekday is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text = "For Sunday: Sunday after (Sunday) November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    assert_eq!(c.for_sunday_second_date, None);
    // And the behind-"on" disagreeing control,
    // unchanged: refused, mismatch recorded.
    let text = "For Sunday: Sunday after on (Monday) November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the behind-on disagreeing weekday is still recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
}

#[test]
fn r35b_bracketed_governing_word_governs_as_its_paren_twin() {
    // Round 35 (R35-B, F2 = review R35-R2): a
    // cancellation word wrapped in brackets or
    // braces inside a group inner did not govern,
    // while its paren-wrapped and bare twins did.
    // `group_token` cleaned a wholly bracketed
    // token to nothing by the round-24 rule —
    // `is_bracketed_token` covers "[]" and "{}"
    // only — while a paren-wrapped token fell
    // through to the edge trim and cleaned to the
    // word itself, so "[cancelled]" read as nothing
    // to the governor checks and behaved exactly
    // like the garnish word "[choir]" in every
    // cell: whole-line, the cancelled date was
    // promoted to the bulletin Sunday in silence;
    // trailing, it killed the date but produced a
    // ParenthesizedDateMismatch record — a
    // cancellation misreported as a date
    // disagreement. The ruling: a governing word
    // governs however it is wrapped — a wholly
    // bracketed or braced token whose word the
    // governor checks themselves recognize cleans
    // to the word, and garnish words keep the
    // round-24 rule untouched. The battery below
    // is the full cross-cell set: 3 outer pairs ×
    // inner forms (bare, paren, bracket, brace) ×
    // whole-line and trailing × cancelled and
    // postponed, on the For line and the
    // Keep-through line, every cell stated
    // outright and compared field for field with
    // the governed canonical (outer parens, bare
    // inner word). November 8, 2026 is a Sunday.
    let outers = [("(", ")"), ("[", "]"), ("{", "}")];
    for word in ["cancelled", "postponed"] {
        let inners = [
            word.to_string(),
            format!("({word})"),
            format!("[{word}]"),
            format!("{{{word}}}"),
        ];
        for (open, close) in outers {
            for inner in &inners {
                // Whole-line: the group is the entire
                // line, and its governed date reads
                // as no date at all, with no record.
                let whole = format!("{open}November 8, 2026 {inner}{close}");
                let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
                assert_eq!(
                    c.for_sunday_parenthesized_mismatch, None,
                    "{whole}: a governed date records no mismatch"
                );
                assert_eq!(
                    c.for_sunday_second_dates,
                    Vec::new(),
                    "{whole}: a governed date is named nowhere live"
                );
                r34e_for_twin(&whole, "(November 8, 2026 cancelled)");
                // Trailing: the core stands, the inner
                // date is killed, and NO mismatch
                // record stands for a governing inner
                // token — the cancellation is the
                // record, in the paren twin's form.
                let trailing = format!("November 1, 2026 {open}November 8, 2026 {inner}{close}");
                let text = format!("For Sunday: {trailing}\n\n## Announcement\n\nHi.\n");
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(c.for_date, Some(nov(1)), "{trailing}: the core stands");
                assert_eq!(
                    c.for_sunday_parenthesized_mismatch, None,
                    "{trailing}: no mismatch record for a governing inner token"
                );
                assert_eq!(
                    c.for_sunday_second_dates,
                    Vec::new(),
                    "{trailing}: the governed date is named nowhere live"
                );
                r34e_for_twin(&trailing, "November 1, 2026 (November 8, 2026 cancelled)");
                // The Keep-through line, whole-line
                // and trailing, in the same cells.
                let keep_whole = format!("{open}November 15, 2026 {inner}{close}");
                let text = format!(
                    "For Sunday: November 1, 2026\nKeep-through: {keep_whole}\n\n## Announcement\n\nHi.\n"
                );
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(
                    c.keep_through, None,
                    "{keep_whole}: the governed keep date reads as none"
                );
                assert_eq!(
                    c.keep_through_parenthesized_mismatch, None,
                    "{keep_whole}: a governed keep date records no mismatch"
                );
                r34e_keep_twin(&keep_whole, "(November 15, 2026 cancelled)");
                let keep_trailing =
                    format!("November 29, 2026 {open}November 15, 2026 {inner}{close}");
                let text = format!(
                    "For Sunday: November 1, 2026\nKeep-through: {keep_trailing}\n\n## Announcement\n\nHi.\n"
                );
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(
                    c.keep_through,
                    Some(nov(29)),
                    "{keep_trailing}: the keep core stands"
                );
                assert_eq!(
                    c.keep_through_parenthesized_mismatch, None,
                    "{keep_trailing}: no mismatch record for a governing inner token"
                );
                r34e_keep_twin(
                    &keep_trailing,
                    "November 29, 2026 (November 15, 2026 cancelled)",
                );
            }
        }
    }
    // The garnish controls keep their standing
    // outcomes exactly, in every wrap: "choir"
    // governs nothing, whole-line or trailing.
    for (open, close) in outers {
        for inner in ["choir", "(choir)", "[choir]", "{choir}"] {
            let whole = format!("{open}November 8, 2026 {inner}{close}");
            let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(
                c.for_date,
                Some(nov(8)),
                "{whole}: the garnish group's date stands"
            );
            assert_eq!(c.for_sunday_parenthesized_mismatch, None, "{whole}");
            let trailing = format!("November 1, 2026 {open}November 8, 2026 {inner}{close}");
            let text = format!("For Sunday: {trailing}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.for_date, Some(nov(1)), "{trailing}: the core stands");
            let m = c
                .for_sunday_parenthesized_mismatch
                .as_ref()
                .expect("the garnish group's date records the standing mismatch");
            assert_eq!(
                m.named,
                nov(8),
                "{trailing}: the mismatch names the group date"
            );
            assert_eq!(m.read, nov(1), "{trailing}: the mismatch reads the core");
        }
    }
}

#[test]
fn r36e_governing_word_wearing_sentence_marks_governs_in_bracket_and_brace_groups_as_its_paren_twin(
) {
    // Round 36 (R36-E, F5 = review R36-5): a governing
    // word wearing one of `! ? ' "` inside a bracket
    // or brace group stopped governing, while its
    // paren-wrapped and bare twins governed:
    // "(November 8, 2026 [cancelled]!)" adopted
    // November 8. `analyze_group` frees a paren-wrapped
    // governor through its paren unwrap, but a
    // bracket/brace-wrapped governor reaches
    // `group_token` still wrapped: `is_bracketed_token`'s
    // trailing trim covered only `, . : ;`, so the
    // token wearing the mark was not recognized as a
    // bracketed unit at all, and `clean_group_word`'s
    // edge trim lacked the same four marks, leaving
    // "cancelled]!" — never a governing word. Marks
    // `;` and `:` governed in all pairs all along;
    // the split was exactly the four missing marks.
    // The ruling (the R35-B principle): a governing
    // word governs however it is wrapped, and however
    // it is punctuated — both trims take the sentence
    // marks, so the wrapped governor cleans to its
    // word in every pair. The battery below is the
    // four marks × both pairs × the governor family
    // (the cancellation singles, the "called off"
    // phrase wrapped whole, the before-governor
    // "not"), whole-line and trailing, on the For
    // line and the Keep-through line, every cell
    // stated outright and compared field for field
    // with its paren twin wearing the same mark; the
    // `;`/`:` controls run through the same cells
    // with their standing outcomes.
    let marks = ["!", "?", "'", "\"", ";", ":"];
    let inners = [("[", "]"), ("{", "}")];
    for word in ["cancelled", "postponed"] {
        for (open, close) in inners {
            for mark in marks {
                // Whole-line: the governed date reads
                // as no date at all, with no record.
                let whole = format!("(November 8, 2026 {open}{word}{close}{mark})");
                let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
                assert_eq!(
                    c.for_sunday_parenthesized_mismatch, None,
                    "{whole}: a governed date records no mismatch"
                );
                assert_eq!(
                    c.for_sunday_second_dates,
                    Vec::new(),
                    "{whole}: a governed date is named nowhere live"
                );
                r34e_for_twin(&whole, &format!("(November 8, 2026 ({word}){mark})"));
                // Trailing: the core stands, the inner
                // date is killed, and no mismatch
                // record stands for the governing token.
                let trailing =
                    format!("November 1, 2026 (November 8, 2026 {open}{word}{close}{mark})");
                let text = format!("For Sunday: {trailing}\n\n## Announcement\n\nHi.\n");
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(c.for_date, Some(nov(1)), "{trailing}: the core stands");
                assert_eq!(
                    c.for_sunday_parenthesized_mismatch, None,
                    "{trailing}: no mismatch record for a governing inner token"
                );
                assert_eq!(
                    c.for_sunday_second_dates,
                    Vec::new(),
                    "{trailing}: the governed date is named nowhere live"
                );
                r34e_for_twin(
                    &trailing,
                    &format!("November 1, 2026 (November 8, 2026 ({word}){mark})"),
                );
                // The Keep-through line, whole-line
                // and trailing, in the same cells.
                let keep_whole = format!("(November 15, 2026 {open}{word}{close}{mark})");
                let text = format!(
                    "For Sunday: November 1, 2026\nKeep-through: {keep_whole}\n\n## Announcement\n\nHi.\n"
                );
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(
                    c.keep_through, None,
                    "{keep_whole}: the governed keep date reads as none"
                );
                assert_eq!(
                    c.keep_through_parenthesized_mismatch, None,
                    "{keep_whole}: a governed keep date records no mismatch"
                );
                r34e_keep_twin(&keep_whole, &format!("(November 15, 2026 ({word}){mark})"));
                let keep_trailing =
                    format!("November 29, 2026 (November 15, 2026 {open}{word}{close}{mark})");
                let text = format!(
                    "For Sunday: November 1, 2026\nKeep-through: {keep_trailing}\n\n## Announcement\n\nHi.\n"
                );
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(
                    c.keep_through,
                    Some(nov(29)),
                    "{keep_trailing}: the keep core stands"
                );
                assert_eq!(
                    c.keep_through_parenthesized_mismatch, None,
                    "{keep_trailing}: no mismatch record for a governing inner token"
                );
                r34e_keep_twin(
                    &keep_trailing,
                    &format!("November 29, 2026 (November 15, 2026 ({word}){mark})"),
                );
            }
        }
    }
    // A third cancellation single, "removed", on the
    // whole-line For cells.
    for (open, close) in inners {
        for mark in marks {
            let whole = format!("(November 8, 2026 {open}removed{close}{mark})");
            let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
            r34e_for_twin(&whole, &format!("(November 8, 2026 (removed){mark})"));
        }
    }
    // The governor phrase wrapped whole: the pair
    // wraps "called off" and the mark rides after
    // the close, on the tail token's edge.
    for (open, close) in inners {
        for mark in marks {
            let whole = format!("(November 8, 2026 {open}called off{close}{mark})");
            let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
            assert_eq!(
                c.for_sunday_parenthesized_mismatch, None,
                "{whole}: a governed date records no mismatch"
            );
            r34e_for_twin(&whole, &format!("(November 8, 2026 (called off){mark})"));
            r34e_keep_twin(&whole, &format!("(November 8, 2026 (called off){mark})"));
        }
    }
    // The before-governor "not" wearing the mark
    // inside its pair, standing before the date.
    for (open, close) in inners {
        for mark in marks {
            let whole = format!("({open}not{close}{mark} November 8, 2026)");
            let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
            r34e_for_twin(&whole, &format!("((not){mark} November 8, 2026)"));
        }
    }
    // The outer pair varies too: a bracket or brace
    // group standing as the whole line, its inner
    // governor in either pair, marks "!" and "?".
    for (oopen, oclose) in inners {
        for (iopen, iclose) in inners {
            for mark in ["!", "?"] {
                let whole =
                    format!("{oopen}November 8, 2026 {iopen}cancelled{iclose}{mark}{oclose}");
                let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
                let c = parse_contribution(&text, today()).expect("parses");
                assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
                r34e_for_twin(&whole, &format!("(November 8, 2026 (cancelled){mark})"));
            }
        }
    }
    // The doubled pair wearing the mark after its
    // outer close governs as its paren twin does.
    for (open, close, popen, pclose) in [("[", "]", "(", ")"), ("{", "}", "(", ")")] {
        for mark in ["!", "?"] {
            let whole = format!("(November 8, 2026 {open}{open}cancelled{close}{close}{mark})");
            let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
            r34e_for_twin(
                &whole,
                &format!("(November 8, 2026 {popen}{popen}cancelled{pclose}{pclose}{mark})"),
            );
        }
    }
    // The mark INSIDE the pair: the shared edge trim
    // takes it off the word in every pair alike, as
    // the bare word wearing the mark governs on a
    // plain line — "[cancelled!]" and "(cancelled!)"
    // govern together.
    for (open, close) in [("[", "]"), ("{", "}"), ("(", ")")] {
        for mark in ["!", "?", "'", "\""] {
            let whole = format!("(November 8, 2026 {open}cancelled{mark}{close})");
            let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
            assert_eq!(
                c.for_sunday_parenthesized_mismatch, None,
                "{whole}: a governed date records no mismatch"
            );
        }
    }
    // The same shared trim, one step further out: a
    // BARE governing word wearing the mark inside a
    // group governs as it does on a plain line —
    // "(November 8, 2026 cancelled!)" and the phrase
    // form "(November 8, 2026 called off!)".
    for mark in marks {
        let whole = format!("(November 8, 2026 cancelled{mark})");
        let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{whole}: the governed date is no Sunday");
    }
    let text = "For Sunday: (November 8, 2026 called off!)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(
        c.for_date, None,
        "the bare phrase wearing \"!\" governs in a group"
    );
    // The garnish controls keep their standing
    // outcomes exactly, wearing any mark: "choir"
    // governs nothing, whole-line or trailing.
    for (open, close) in inners {
        for mark in marks {
            let whole = format!("(November 8, 2026 {open}choir{close}{mark})");
            let text = format!("For Sunday: {whole}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(
                c.for_date,
                Some(nov(8)),
                "{whole}: the garnish group's date stands"
            );
            assert_eq!(c.for_sunday_parenthesized_mismatch, None, "{whole}");
            let trailing = format!("November 1, 2026 (November 8, 2026 {open}choir{close}{mark})");
            let text = format!("For Sunday: {trailing}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.for_date, Some(nov(1)), "{trailing}: the core stands");
            let m = c
                .for_sunday_parenthesized_mismatch
                .as_ref()
                .expect("the garnish group's date records the standing mismatch");
            assert_eq!(
                m.named,
                nov(8),
                "{trailing}: the mismatch names the group date"
            );
            assert_eq!(m.read, nov(1), "{trailing}: the mismatch reads the core");
        }
    }
}

#[test]
fn r35c_glued_weekday_group_judges_as_its_spaced_twin_at_leading_and_month_day_slots() {
    // Round 35 (R35-C, F3 = review R35-R3 = red team
    // RT35-4): the R33-B re-spacing gate judged only a
    // TRAILING glued weekday garnish. At the leading
    // slot and the month–day slot a glued weekday
    // group was invisible to every reader, in all
    // three pairs: "(Monday)November 1, 2026" read the
    // date in silence where spaced "(Monday) November
    // 1, 2026" refuses it and records the mismatch, and
    // "November(Monday) 1, 2026" read the date where
    // the spaced twin — and the bare word — read no
    // date at all, agreeing or disagreeing, on the For
    // line and the Keep-through line alike. The ruling
    // (the R33-B/R34-C doctrine): spacing is not
    // semantics — a glued weekday group judges exactly
    // as its spaced twin at every slot, whichever way
    // the slot's standing spaced reading judges. Every
    // pair below compares the glued line's FULL record
    // against its spaced twin's (the r34e helpers), and
    // the witnessed forms are stated outright after.
    // November 1 and November 8, 2026 are Sundays:
    // "Monday" disagrees, "Sunday" agrees. At the
    // month–day slot the spaced reading is for=None
    // with NO record, for both words — the group
    // interrupts the date the bare word interrupts —
    // so the glued twin's equality there is equality
    // of refusal, not of judgment by weekday.
    let pairs = [("(", ")"), ("[", "]"), ("{", "}")];
    for (open, close) in pairs {
        for word in ["Monday", "Sunday"] {
            // The leading slot: the group stands glued
            // against the month word on its right.
            let glued_lead = format!("{open}{word}{close}November 1, 2026");
            let spaced_lead = format!("{open}{word}{close} November 1, 2026");
            r34e_for_twin(&glued_lead, &spaced_lead);
            r34e_for_twin(&glued_lead, &format!("({word}) November 1, 2026"));
            let glued_lead_keep = format!("{open}{word}{close}November 8, 2026");
            let spaced_lead_keep = format!("{open}{word}{close} November 8, 2026");
            r34e_keep_twin(&glued_lead_keep, &spaced_lead_keep);
            // The month–day slot: the group stands
            // glued against the month word on its left.
            let glued_mid = format!("November{open}{word}{close} 1, 2026");
            let spaced_mid = format!("November {open}{word}{close} 1, 2026");
            r34e_for_twin(&glued_mid, &spaced_mid);
            r34e_for_twin(&glued_mid, &format!("November ({word}) 1, 2026"));
            let glued_mid_keep = format!("November{open}{word}{close} 8, 2026");
            let spaced_mid_keep = format!("November {open}{word}{close} 8, 2026");
            r34e_keep_twin(&glued_mid_keep, &spaced_mid_keep);
        }
        // The witnessed disagreeing forms, stated
        // outright. Leading: the date is refused and
        // the mismatch is recorded, as spaced records.
        let glued_lead = format!("{open}Monday{close}November 1, 2026");
        let text = format!("For Sunday: {glued_lead}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{glued_lead}");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing glued leading weekday is recorded");
        assert_eq!(m.named, "Monday", "{glued_lead}");
        assert_eq!(m.date, nov(1), "{glued_lead}");
        let glued_lead_keep = format!("{open}Monday{close}November 8, 2026");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {glued_lead_keep}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{glued_lead_keep}");
        let m = c
            .keep_through_weekday_mismatch
            .as_ref()
            .expect("the disagreeing glued leading weekday on the keep line is recorded");
        assert_eq!(m.named, "Monday", "{glued_lead_keep}");
        assert_eq!(m.date, nov(8), "{glued_lead_keep}");
        // Month–day: no date reads and no record
        // stands, for the disagreeing word AND the
        // agreeing one, exactly as the spaced forms
        // read (and as the bare word reads).
        for word in ["Monday", "Sunday"] {
            let glued_mid = format!("November{open}{word}{close} 1, 2026");
            let text = format!("For Sunday: {glued_mid}\n\n## Announcement\n\nHi.\n");
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.for_date, None, "{glued_mid}: no date reads");
            assert_eq!(c.named_weekday_mismatch, None, "{glued_mid}: no record");
            let glued_mid_keep = format!("November{open}{word}{close} 8, 2026");
            let text = format!(
                "For Sunday: November 1, 2026\nKeep-through: {glued_mid_keep}\n\n## Announcement\n\nHi.\n"
            );
            let c = parse_contribution(&text, today()).expect("parses");
            assert_eq!(c.keep_through, None, "{glued_mid_keep}: no keep date reads");
            assert_eq!(
                c.keep_through_weekday_mismatch, None,
                "{glued_mid_keep}: no record"
            );
        }
        // The agreeing leading group reads the date
        // clean, as its spaced twin does.
        let glued_lead_agree = format!("{open}Sunday{close}November 1, 2026");
        let text = format!("For Sunday: {glued_lead_agree}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(1)), "{glued_lead_agree}");
        assert_eq!(c.named_weekday_mismatch, None, "{glued_lead_agree}");
    }
    // The month–day slot's compound shapes, in the
    // paren pair: a comma after the group, a doubled
    // group, and two glued groups in a row judge as
    // their spaced twins.
    r34e_for_twin("November(Monday), 1, 2026", "November (Monday), 1, 2026");
    r34e_for_twin("November((Monday)) 1, 2026", "November ((Monday)) 1, 2026");
    r34e_for_twin(
        "November(Monday)(Sunday) 1, 2026",
        "November (Monday) (Sunday) 1, 2026",
    );
    r34e_keep_twin("November(Monday), 8, 2026", "November (Monday), 8, 2026");
    // The red team's witnessed Keep-through line,
    // stated outright (its For Sunday line is
    // November 8 in the witness; the keep date and
    // its refusal are the witness's own): glued keeps
    // nothing, exactly as spaced keeps nothing.
    let text =
        "For Sunday: November 1, 2026\nKeep-through: November[Monday] 15, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, None);
    assert_eq!(c.keep_through_weekday_mismatch, None);
    // A leading group wearing a peel mark against the
    // month word — "(Monday)'November 1, 2026" — sets
    // its space after the mark and judges as its
    // spaced twin "(Monday)' November 1, 2026".
    r34e_for_twin("(Monday)'November 1, 2026", "(Monday)' November 1, 2026");
    r34e_for_twin(
        "(Monday)\u{201d}November 1, 2026",
        "(Monday)\u{201d} November 1, 2026",
    );
    // The day–year slot is coherent already and is
    // NOT this fix's: its glued and spaced forms both
    // read the date clean with no record, and both
    // keep that reading here.
    r34e_for_twin("November 1(Monday), 2026", "November 1 (Monday), 2026");
    let text = "For Sunday: November 1(Monday), 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(1)));
    assert_eq!(c.named_weekday_mismatch, None);
}

#[test]
fn r36c_any_standalone_group_at_the_month_day_slot_takes_its_spaced_reading() {
    // Round 36 (R36-C, F1 MAJOR arm + F10 = review
    // R36-1 = red team RT36-2 = verify target (a)):
    // the R35-C re-spacing gate re-spaced only a
    // standalone group holding one weekday word in
    // openers of one pair. Past that pattern, at the
    // month–day slot, glued and spaced split for
    // every other standalone group: a governing
    // group served its date live in the glued form
    // ("November(cancelled) 1, 2026" read November 1
    // with no record; the spaced twin and the bare
    // twin read nothing — likewise "(postponed)" and
    // the multi-word governor "[called off]"); a
    // glued date group read the outer date with a
    // record naming the group's date
    // ("November(November 8, 2026) 1, 2026" read
    // November 1, record naming November 8, where
    // the spaced twin reads November 8 clean); a
    // mixed-pair wrapper escaped even for weekday
    // contents; and inert contents flipped
    // date-vs-no-date on one space ("November(notes)
    // 1, 2026" read, "November (notes) 1, 2026" read
    // nothing, identically for [] and {} and for
    // choir and the other inert words the lanes
    // tried). The adjudicated reading for the whole
    // slot is the standing one: spacing is not
    // semantics — the glued form takes the spaced
    // form's reading. The gate's new date-slot pass
    // re-spaces a standalone group of ANY contents
    // at this slot from its balanced span, mixed
    // and doubled wrappers included. Every pair
    // below compares the glued line's FULL record
    // against its spaced twin's (the r34e helpers),
    // on the For line and the Keep-through line, and
    // the headline forms are stated outright after.
    // November 1 and November 8, 2026 are Sundays.
    let contents = [
        "cancelled",
        "postponed",
        "called off",
        "notes",
        "choir",
        "note",
        "rehearsal",
        "potluck",
        "meeting",
        "x",
        "Monday",
        "Sunday",
    ];
    for (open, close) in [("(", ")"), ("[", "]"), ("{", "}")] {
        for content in contents {
            let glued = format!("November{open}{content}{close} 1, 2026");
            let spaced = format!("November {open}{content}{close} 1, 2026");
            r34e_for_twin(&glued, &spaced);
            let glued_keep = format!("November{open}{content}{close} 8, 2026");
            let spaced_keep = format!("November {open}{content}{close} 8, 2026");
            r34e_keep_twin(&glued_keep, &spaced_keep);
        }
    }
    // A glued date group: the spaced reading stands
    // — the group's own date reads, clean.
    for (open, close) in [("(", ")"), ("[", "]"), ("{", "}")] {
        let glued = format!("November{open}November 8, 2026{close} 1, 2026");
        let spaced = format!("November {open}November 8, 2026{close} 1, 2026");
        r34e_for_twin(&glued, &spaced);
        r34e_keep_twin(&glued, &spaced);
    }
    // Doubled wrappers with non-weekday contents,
    // and the doubled weekday control whose outcome
    // R35-C already pinned (unweakened here).
    for group in ["((notes))", "[[cancelled]]", "{{choir}}", "((Monday))"] {
        let glued = format!("November{group} 1, 2026");
        let spaced = format!("November {group} 1, 2026");
        r34e_for_twin(&glued, &spaced);
        let glued_keep = format!("November{group} 8, 2026");
        let spaced_keep = format!("November {group} 8, 2026");
        r34e_keep_twin(&glued_keep, &spaced_keep);
    }
    // Mixed-pair wrappers, disagreeing and agreeing.
    for group in [
        "([Monday])",
        "[(Monday)]",
        "{[Monday]}",
        "{(Monday)}",
        "([Sunday])",
        "[(Sunday)]",
    ] {
        let glued = format!("November{group} 1, 2026");
        let spaced = format!("November {group} 1, 2026");
        r34e_for_twin(&glued, &spaced);
        r34e_keep_twin(&glued, &spaced);
    }
    // Stated outright, the headline forms. The
    // governing glued forms read no date and stand
    // no record, as their spaced and bare twins read.
    for line in [
        "November(cancelled) 1, 2026",
        "November(postponed) 1, 2026",
        "November[called off] 1, 2026",
        "November(notes) 1, 2026",
        "November([Monday]) 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date reads");
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no record");
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: no parenthesized record"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: no keep date reads");
    }
    // The glued date group reads its group's date
    // clean, on both routes.
    let text = "For Sunday: November(November 8, 2026) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
    let text = "For Sunday: November 1, 2026\nKeep-through: November(November 8, 2026) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, Some(nov(8)));
    assert_eq!(c.keep_through_parenthesized_mismatch, None);
}

#[test]
fn r37c_two_group_compound_glued_at_the_month_day_slot_takes_its_spaced_reading() {
    // Round 37 (R37-C, F5 MAJOR + F6 MINOR = verify
    // V4/V5 = review R37-R3/R37-R7 = red team
    // RT37-4/RT37-6): two-group compounds glued at
    // the month–day slot escaped the R36-C date-slot
    // pass entirely. The pass iterates top-level
    // balanced spans and qualifies a span by its own
    // neighbours — a month word before it, a day
    // number after it — so in a glued compound
    // neither span qualifies: the first is followed
    // by a group, not a day digit, and the second is
    // preceded by a group, not a month word. The
    // compound was never re-spaced, and its glued
    // reading split from its spaced twin's by
    // contents: a governing group in either position
    // served the date live with no record
    // ("November(cancelled)(notes) 1, 2026" and
    // "November(notes)(cancelled) 1, 2026" read
    // November 1; the spaced twins read nothing), a
    // mixed weekday wrapper served silently
    // ("November([Monday])(notes) 1, 2026"), a date
    // group first flipped the reading to the outer
    // date with a mismatch record
    // ("November(November 8, 2026)(notes) 1, 2026"
    // read November 1 naming November 8, where the
    // spaced twin reads November 8 clean), and inert
    // compounds read November 1 glued, nothing spaced
    // ("November(notes)(choir) 1, 2026" and its
    // mixed-pair, repeated, and doubled forms). The
    // adjudicated reading is the standing one:
    // spacing is not semantics — the compound
    // standing at the slot (first group glued to the
    // month word, day number after the second group)
    // takes its spaced reading as a unit. Every pair
    // below compares the glued line's FULL record
    // against its spaced twins' (both the twin spaced
    // only after the month word — the form the lanes
    // witnessed — and the fully-spaced form), on the
    // For line and the Keep-through line, via the
    // r34e helpers; the headline forms are stated
    // outright after. November 1 and November 8,
    // 2026 are Sundays.
    let pair_shapes: [(&str, &str, &str, &str); 5] = [
        ("(", ")", "(", ")"),
        ("[", "]", "[", "]"),
        ("{", "}", "{", "}"),
        ("(", ")", "[", "]"),
        ("[", "]", "(", ")"),
    ];
    // Governing contents in either position, the
    // multi-word governor included, and the inert
    // family (plain, repeated).
    let content_pairs: [(&str, &str); 7] = [
        ("cancelled", "notes"),
        ("notes", "cancelled"),
        ("called off", "notes"),
        ("notes", "called off"),
        ("postponed", "choir"),
        ("notes", "choir"),
        ("notes", "notes"),
    ];
    for (o1, c1, o2, c2) in pair_shapes {
        for (first, second) in content_pairs {
            let glued = format!("November{o1}{first}{c1}{o2}{second}{c2} 1, 2026");
            let half_spaced = format!("November {o1}{first}{c1}{o2}{second}{c2} 1, 2026");
            let spaced = format!("November {o1}{first}{c1} {o2}{second}{c2} 1, 2026");
            r34e_for_twin(&glued, &half_spaced);
            r34e_for_twin(&glued, &spaced);
            r34e_keep_twin(&glued, &half_spaced);
            r34e_keep_twin(&glued, &spaced);
        }
    }
    // A date group in either position, and the
    // mixed weekday wrapper in either position.
    for compound in [
        "(November 8, 2026)(notes)",
        "(notes)(November 8, 2026)",
        "[November 8, 2026][notes]",
        "([Monday])(notes)",
        "(notes)([Monday])",
        "([Sunday])(notes)",
        // The doubled wrappers, as a compound.
        "((notes))((choir))",
        "((cancelled))((notes))",
        // Weekday-only compounds: twin-equal before
        // this batch (the lanes' held control) and
        // unweakened here.
        "(Monday)(notes)",
        "(notes)(Monday)",
        "(Sunday)(notes)",
        "(Monday)(Sunday)",
    ] {
        let glued = format!("November{compound} 1, 2026");
        let half_spaced = format!("November {compound} 1, 2026");
        r34e_for_twin(&glued, &half_spaced);
        r34e_keep_twin(&glued, &half_spaced);
    }
    // The fully-spaced twins of the wrapped forms,
    // stated as pairs in their own right.
    r34e_for_twin(
        "November([Monday])(notes) 1, 2026",
        "November ([Monday]) (notes) 1, 2026",
    );
    r34e_keep_twin(
        "November([Monday])(notes) 1, 2026",
        "November ([Monday]) (notes) 1, 2026",
    );
    r34e_for_twin(
        "November((notes))((choir)) 1, 2026",
        "November ((notes)) ((choir)) 1, 2026",
    );
    r34e_keep_twin(
        "November((notes))((choir)) 1, 2026",
        "November ((notes)) ((choir)) 1, 2026",
    );
    r34e_for_twin(
        "November(November 8, 2026)(notes) 1, 2026",
        "November (November 8, 2026) (notes) 1, 2026",
    );
    r34e_keep_twin(
        "November(November 8, 2026)(notes) 1, 2026",
        "November (November 8, 2026) (notes) 1, 2026",
    );
    // Spaced-inside contents: the spaces inside the
    // groups are the sender's, and the compound is
    // still the compound at the slot.
    r34e_for_twin(
        "November( notes )( choir ) 1, 2026",
        "November ( notes )( choir ) 1, 2026",
    );
    r34e_keep_twin(
        "November( notes )( choir ) 1, 2026",
        "November ( notes )( choir ) 1, 2026",
    );
    // Stated outright, the headline forms. A
    // governing group in either position — and the
    // multi-word governor — reads no date and stands
    // no record, as its spaced twins read, on both
    // routes.
    for line in [
        "November(cancelled)(notes) 1, 2026",
        "November(notes)(cancelled) 1, 2026",
        "November(called off)(notes) 1, 2026",
        "November(notes)(called off) 1, 2026",
        "November([Monday])(notes) 1, 2026",
        "November(notes)(choir) 1, 2026",
        "November[notes][choir] 1, 2026",
        "November{notes}{choir} 1, 2026",
        "November(notes)[choir] 1, 2026",
        "November((notes))((choir)) 1, 2026",
        "November(notes)(notes) 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date reads");
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no record");
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: no parenthesized record"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: no keep date reads");
        assert_eq!(
            c.keep_through_parenthesized_mismatch, None,
            "{line}: no keep parenthesized record"
        );
    }
    // The date group first: the compound takes the
    // spaced reading — the group's own date reads,
    // clean, on both routes.
    let text = "For Sunday: November(November 8, 2026)(notes) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
    let text = "For Sunday: November 1, 2026\nKeep-through: November(November 8, 2026)(notes) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, Some(nov(8)));
    assert_eq!(c.keep_through_parenthesized_mismatch, None);
    // The half-glued control, unweakened: the first
    // group glued and the second standing apart was
    // twin-equal before this batch (the single-group
    // pass already reaches the form's reading) and
    // keeps it — no date reads, on both routes.
    r34e_for_twin(
        "November(notes) (choir) 1, 2026",
        "November (notes) (choir) 1, 2026",
    );
    r34e_keep_twin(
        "November(notes) (choir) 1, 2026",
        "November (notes) (choir) 1, 2026",
    );
    let text = "For Sunday: November(notes) (choir) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    // The weekday-only compound control, stated
    // outright at its standing reading: the
    // disagreeing weekday compound reads no date,
    // glued exactly as spaced.
    let text = "For Sunday: November(Monday)(notes) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let text = "For Sunday: November(notes)(Monday) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
}

#[test]
fn r37c_three_group_compound_glued_at_the_month_day_slot_takes_its_spaced_reading() {
    // Round 37 (R37-C, F5/F6 scope answer): chains
    // longer than two groups were unwitnessed by
    // the lanes. The compound rule keys on the chain
    // standing at the slot — first group glued to
    // the month word, day number after the chain's
    // last group — so it generalizes to a chain of
    // any length without a second mechanism, and
    // the three-group forms are pinned here rather
    // than left to the generalization's say-so:
    // inert, governing in the middle, and a date
    // group first, each compared field for field
    // against its spaced twin on both routes, the
    // governing and date forms stated outright.
    // November 1 and November 8, 2026 are Sundays.
    for (glued, spaced) in [
        (
            "November(notes)(choir)(rehearsal) 1, 2026",
            "November (notes) (choir) (rehearsal) 1, 2026",
        ),
        (
            "November(notes)(cancelled)(choir) 1, 2026",
            "November (notes) (cancelled) (choir) 1, 2026",
        ),
        (
            "November(November 8, 2026)(notes)(choir) 1, 2026",
            "November (November 8, 2026) (notes) (choir) 1, 2026",
        ),
        (
            "November[notes]{choir}(rehearsal) 1, 2026",
            "November [notes] {choir} (rehearsal) 1, 2026",
        ),
    ] {
        r34e_for_twin(glued, spaced);
        r34e_keep_twin(glued, spaced);
    }
    let text = "For Sunday: November(notes)(cancelled)(choir) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
    let text =
        "For Sunday: November(November 8, 2026)(notes)(choir) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
    let text = "For Sunday: November 1, 2026\nKeep-through: November(November 8, 2026)(notes)(choir) 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, Some(nov(8)));
    assert_eq!(c.keep_through_parenthesized_mismatch, None);
}

#[test]
fn r37d_weekday_group_with_a_companion_group_is_judged_at_the_leading_and_trailing_slots() {
    // Round 37 (R37-D, F7 MAJOR = review R37-R4):
    // a weekday group with any companion group
    // beside it escaped judgment at the leading and
    // trailing slots, in every spacing. The lone
    // forms refuse with the record at both slots —
    // "(Monday)November 1, 2026" and "November 1,
    // 2026 (Monday)" both record
    // WeekdayMismatch(Monday@2026-11-01) — but
    // appending one inert group, glued, spaced, or
    // comma-separated, in either position, served
    // the date silently on both routes:
    // "(Monday)(notes)November 1, 2026",
    // "(Monday) (notes) November 1, 2026",
    // "[Monday][notes]November 1, 2026",
    // "([Monday])(notes)November 1, 2026",
    // "November 1, 2026 (notes)(Monday)",
    // "November 1, 2026 (Monday) (notes)". The
    // month–day slot judges weekday compounds in
    // every form (R37-C's controls), so the
    // machinery walks compound groups where its
    // readers reach them; the leading and trailing
    // garnish readers stopped at one group — the
    // framing reader asked for the date directly
    // after its weekday token, and the trailing
    // reader asked only for the line's last word.
    // The garnish judgments now walk the group
    // sequence standing at the slot
    // (`group_sequence_weekday_mismatch` in
    // composition.rs), as the month–day readers do:
    // a weekday group standing at the slot is
    // judged on its contents whether it stands
    // alone or with companion groups beside it.
    // Every pair below compares a companion form's
    // FULL record against its lone-group twin's
    // (the r34e helpers), on the For line and the
    // Keep-through line; the headline forms are
    // stated outright after. November 1, 2026 is a
    // Sunday: "Monday" disagrees, "Sunday" agrees.
    let pair_shapes: [(&str, &str, &str, &str); 5] = [
        ("(", ")", "(", ")"),
        ("[", "]", "[", "]"),
        ("{", "}", "{", "}"),
        ("(", ")", "[", "]"),
        ("[", "]", "(", ")"),
    ];
    for (o1, c1, o2, c2) in pair_shapes {
        for word in ["Monday", "Sunday"] {
            let w = format!("{o1}{word}{c1}");
            let n = format!("{o2}notes{c2}");
            // Leading, the weekday group first and
            // the companion first, in every spacing
            // the lone forms allow.
            for compound in [
                format!("{w}{n}November 1, 2026"),
                format!("{w} {n}November 1, 2026"),
                format!("{w}{n} November 1, 2026"),
                format!("{w} {n} November 1, 2026"),
                format!("{n}{w}November 1, 2026"),
                format!("{n} {w} November 1, 2026"),
                format!("{w}, {n}, November 1, 2026"),
                format!("{w} {n}, November 1, 2026"),
            ] {
                let lone = format!("{w}November 1, 2026");
                r34e_for_twin(&compound, &lone);
                r34e_keep_twin(&compound, &lone);
            }
            // Trailing, both orders, spaced, glued
            // against the year, and comma-separated.
            for compound in [
                format!("November 1, 2026 {w}{n}"),
                format!("November 1, 2026 {w} {n}"),
                format!("November 1, 2026 {n}{w}"),
                format!("November 1, 2026 {n} {w}"),
                format!("November 1, 2026, {n}, {w}"),
                format!("November 1, 2026 {n}, {w}"),
            ] {
                let lone = format!("November 1, 2026 {w}");
                r34e_for_twin(&compound, &lone);
                r34e_keep_twin(&compound, &lone);
            }
            let glued_compound = format!("November 1, 2026{w}{n}");
            let glued_lone = format!("November 1, 2026{w}");
            r34e_for_twin(&glued_compound, &glued_lone);
            r34e_keep_twin(&glued_compound, &glued_lone);
        }
    }
    // The mixed-pair wrapper and the doubled
    // wrapper as the weekday group, with a
    // companion beside them, at both slots.
    for compound in [
        "([Monday])(notes)November 1, 2026",
        "(notes)([Monday])November 1, 2026",
        "((Monday))((notes))November 1, 2026",
        "((notes))((Monday))November 1, 2026",
    ] {
        r34e_for_twin(compound, "([Monday])November 1, 2026");
        r34e_keep_twin(compound, "([Monday])November 1, 2026");
    }
    for compound in [
        "November 1, 2026 ([Monday])(notes)",
        "November 1, 2026 (notes)([Monday])",
        "November 1, 2026 ((Monday))((notes))",
        "November 1, 2026 ((notes))((Monday))",
    ] {
        r34e_for_twin(compound, "November 1, 2026 ([Monday])");
        r34e_keep_twin(compound, "November 1, 2026 ([Monday])");
    }
    for compound in [
        "([Sunday])(notes)November 1, 2026",
        "(notes)([Sunday])November 1, 2026",
    ] {
        r34e_for_twin(compound, "([Sunday])November 1, 2026");
        r34e_keep_twin(compound, "([Sunday])November 1, 2026");
    }
    for compound in [
        "November 1, 2026 ([Sunday])(notes)",
        "November 1, 2026 (notes)([Sunday])",
    ] {
        r34e_for_twin(compound, "November 1, 2026 ([Sunday])");
        r34e_keep_twin(compound, "November 1, 2026 ([Sunday])");
    }
    // Three-group sequences: the weekday group
    // first, last, and in the middle, at both
    // slots — the walk is over the sequence, not
    // over a pair.
    for compound in [
        "(Monday)(notes)(choir)November 1, 2026",
        "(notes)(choir)(Monday)November 1, 2026",
        "(notes)(Monday)(choir)November 1, 2026",
        "(Monday) (notes) (choir) November 1, 2026",
    ] {
        r34e_for_twin(compound, "(Monday)November 1, 2026");
        r34e_keep_twin(compound, "(Monday)November 1, 2026");
    }
    for compound in [
        "November 1, 2026 (Monday)(notes)(choir)",
        "November 1, 2026 (notes)(choir)(Monday)",
        "November 1, 2026 (notes)(Monday)(choir)",
        "November 1, 2026 (notes) (choir) (Monday)",
    ] {
        r34e_for_twin(compound, "November 1, 2026 (Monday)");
        r34e_keep_twin(compound, "November 1, 2026 (Monday)");
    }
    // The framing garnish stack in front of the
    // leading sequence, as it stands in front of
    // the lone group: the sequence behind it is
    // judged the same way.
    for compound in [
        "on (Monday) (notes) November 1, 2026",
        "the (Monday) (notes) November 1, 2026",
        "on the (Monday) (notes) November 1, 2026",
        "on (notes) (Monday) November 1, 2026",
    ] {
        r34e_for_twin(compound, "on (Monday) November 1, 2026");
        r34e_keep_twin(compound, "on (Monday) November 1, 2026");
    }
    for compound in [
        "on (Sunday) (notes) November 1, 2026",
        "on the (notes) (Sunday) November 1, 2026",
    ] {
        r34e_for_twin(compound, "on (Sunday) November 1, 2026");
        r34e_keep_twin(compound, "on (Sunday) November 1, 2026");
    }
    // Stated outright, the headline forms. A
    // disagreeing weekday group with a companion
    // is refused with the lone form's record, on
    // both routes, at both slots.
    for line in [
        "(Monday)(notes)November 1, 2026",
        "(Monday) (notes) November 1, 2026",
        "[Monday][notes]November 1, 2026",
        "([Monday])(notes)November 1, 2026",
        "(notes)(Monday)November 1, 2026",
        "November 1, 2026 (notes)(Monday)",
        "November 1, 2026 (Monday)(notes)",
        "November 1, 2026 (Monday) (notes)",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date reads");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing weekday group with a companion is recorded");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: a weekday refusal carries no parenthesized record"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: no keep date reads");
        let m = c
            .keep_through_weekday_mismatch
            .as_ref()
            .expect("the disagreeing weekday group is recorded on the keep line");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
    }
    // The agreeing arm converges: an agreeing
    // weekday group with a companion is consumed
    // exactly as the lone agreeing group is — the
    // date reads clean, with no record, on both
    // routes, at both slots.
    for line in [
        "(Sunday)(notes)November 1, 2026",
        "(notes)(Sunday)November 1, 2026",
        "(Sunday) (notes) November 1, 2026",
        "November 1, 2026 (notes)(Sunday)",
        "November 1, 2026 (Sunday)(notes)",
        "November 1, 2026 (Sunday) (notes)",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(1)), "{line}: the date reads");
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no record");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, Some(nov(1)), "{line}: the keep date reads");
        assert_eq!(c.keep_through_weekday_mismatch, None, "{line}: no record");
    }
    // Both slots carrying sequences at once: the
    // leading sequence is judged first, as the
    // lone framings are — an agreeing leading
    // sequence leaves the trailing sequence to
    // speak, and a disagreeing leading sequence
    // speaks over an agreeing trailing one.
    let text =
        "For Sunday: (Sunday)(notes)November 1, 2026 (Monday)(notes)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing trailing sequence is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text =
        "For Sunday: (Monday)(notes)November 1, 2026 (Sunday)(notes)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing leading sequence is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    // Words after the date are the remainder, as
    // they are for the lone framing: the leading
    // sequence in front of such a date is judged.
    r34e_for_twin(
        "(Monday) (notes) November 1, 2026 for the picnic",
        "(Monday) November 1, 2026 for the picnic",
    );
    r34e_keep_twin(
        "(Monday) (notes) November 1, 2026 for the picnic",
        "(Monday) November 1, 2026 for the picnic",
    );
}

#[test]
fn r37d_companion_contents_keep_their_standing_judgments_and_the_r5d_boundary_stands() {
    // Round 37 (R37-D, F7), the companion side of
    // the walk and the doctrine boundary it must
    // not cross. The walk judges the weekday group
    // and nothing else: it adopts nothing and
    // governs nothing, so a companion whose
    // contents carry their own judgment keeps it.
    // A governing companion beside a disagreeing
    // weekday group changes nothing about the
    // weekday's refusal, and a trailing
    // "(cancelled)" group leaves the core to the
    // weekday exactly as it leaves it to the
    // standing readers.
    // Round 38 (R38-D, F4) RESTATES the leading
    // arms of this pin outright, flagged in the
    // batch's writer note: the round-37 text here
    // recorded that "a wrapped leading governor is
    // garnish, per the standing uniform cell", and
    // the leading arms were pinned against the
    // lone weekday forms. Under the doctrine
    // adopted in the round-38 synthesis
    // (adjudication 4) a leading group's governor
    // contents are judged as the bare governor is
    // judged, so the leading arms are now pinned
    // against their governor-bared twins: beside a
    // disagreeing weekday the refusal record is the
    // twin's (the weekday still speaks), and beside
    // an agreeing weekday the governor governs and
    // the line reads nothing, as its twin reads
    // nothing. The trailing arms below are
    // unchanged (coordinator ruling r38d-ruling.md:
    // the doctrine change is leading-slot only).
    // Round 39 (R39-H, F10) RESTATES the trailing
    // arms of this pin outright, flagged in the
    // batch record: the round-39 synthesis
    // (adjudication 3) extended the doctrine to the
    // trailing slot, so the trailing governor arms
    // are now pinned against their governor-bared
    // twins, exactly as the leading arms were in
    // R38-D — beside a disagreeing weekday the
    // governor governs and the weekday's record
    // falls with the date, as it falls beside the
    // bare governor today; beside an agreeing
    // weekday the governor governs and the line
    // reads nothing. The date-carrying trailing
    // arms below are unchanged (a date group is not
    // a governor group, at any slot).
    for (compound, twin) in [
        (
            "(Monday)(cancelled)November 1, 2026",
            "(Monday) cancelled November 1, 2026",
        ),
        (
            "November 1, 2026 (Monday)(cancelled)",
            "November 1, 2026 (Monday) cancelled",
        ),
        (
            "November 1, 2026 (cancelled)(Monday)",
            "November 1, 2026 cancelled (Monday)",
        ),
    ] {
        r34e_for_twin(compound, twin);
        r34e_keep_twin(compound, twin);
    }
    // Round 40 (R40-E, F9) RESTATES the leading
    // governor-first arm of this pin outright,
    // flagged here and in the batch record: the
    // arm below stood in the loop above as the
    // twin pair "(cancelled)(Monday)November 1,
    // 2026" / "cancelled (Monday) November 1,
    // 2026", and on the audited tree both dresses
    // SERVED November 1 silently — the governor
    // unwrap bared the governor group before the
    // sequence walk could judge the weekday group
    // standing in the same leading sequence, so
    // the twin comparison encoded the serving
    // reading while appearing to pin a refusal.
    // Under adjudication 3 of the round-40
    // synthesis the company composes: governed,
    // with WeekdayMismatch(Monday@2026-11-01)
    // recorded, in both dresses, stated outright
    // here (the full company is pinned in the
    // r40e pin set at the end of this file).
    r40e_governed_with_record("(cancelled)(Monday)November 1, 2026", "Monday", nov(1));
    r40e_governed_with_record("cancelled (Monday) November 1, 2026", "Monday", nov(1));
    for (compound, twin) in [
        (
            "(Sunday)(cancelled)November 1, 2026",
            "(Sunday) cancelled November 1, 2026",
        ),
        (
            "(cancelled)(Sunday)November 1, 2026",
            "cancelled (Sunday) November 1, 2026",
        ),
    ] {
        r34e_for_twin(compound, twin);
        r34e_keep_twin(compound, twin);
    }
    for (compound, twin) in [
        (
            "November 1, 2026 (Sunday)(cancelled)",
            "November 1, 2026 (Sunday) cancelled",
        ),
        (
            "November 1, 2026 (cancelled)(Sunday)",
            "November 1, 2026 cancelled (Sunday)",
        ),
    ] {
        r34e_for_twin(compound, twin);
        r34e_keep_twin(compound, twin);
    }
    // A date-carrying companion: beside a
    // disagreeing weekday group the weekday
    // refusal stands, with no parenthesized record
    // (the standing precedence — a wrong weekday
    // speaks first, and its refusal carries none);
    // the walk does not adopt the companion's
    // date in any form.
    for compound in [
        "(Monday)(November 8, 2026)November 1, 2026",
        "(November 8, 2026)(Monday)November 1, 2026",
        "November 1, 2026 (Monday)(November 8, 2026)",
        "November 1, 2026 (November 8, 2026)(Monday)",
    ] {
        let lone = if compound.starts_with("November 1") {
            "November 1, 2026 (Monday)"
        } else {
            "(Monday)November 1, 2026"
        };
        r34e_for_twin(compound, lone);
        r34e_keep_twin(compound, lone);
    }
    // Beside an agreeing weekday group the date
    // companion's own garnish comparison stands
    // exactly as it stands without the weekday
    // group: the line reads November 1 and the
    // November 8 group is recorded against it,
    // except in the one order whose standing
    // reading has never carried the comparison —
    // the date group standing first at the leading
    // slot — which is unchanged here too.
    for line in [
        "(Sunday)(November 8, 2026)November 1, 2026",
        "November 1, 2026 (Sunday)(November 8, 2026)",
        "November 1, 2026 (November 8, 2026)(Sunday)",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(1)), "{line}: the line's date reads");
        assert_eq!(
            c.named_weekday_mismatch, None,
            "{line}: the agreeing weekday is silent"
        );
        let m = c
            .for_sunday_parenthesized_mismatch
            .as_ref()
            .expect("the date companion's garnish comparison stands");
        assert_eq!(m.named, nov(8), "{line}");
        assert_eq!(m.read, nov(1), "{line}");
    }
    let text = "For Sunday: (November 8, 2026)(Sunday)November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(1)));
    assert_eq!(c.named_weekday_mismatch, None);
    assert_eq!(c.for_sunday_parenthesized_mismatch, None);
    // The R5-D adjacency doctrine, stated outright
    // and UNCHANGED in this same pin set, so the
    // boundary between the doctrine and the fix is
    // pinned, not implied: a BARE word between the
    // weekday group and the date leaves the
    // weekday ordinary text — the date reads and
    // no mismatch is recorded — because the walk
    // walks groups, and a bare word ends the
    // sequence. The same holds behind the framing
    // stack and with a group standing before the
    // bare word.
    for line in [
        "(Monday) notes November 1, 2026",
        "(Monday) notes, November 1, 2026",
        "on (Monday) notes November 1, 2026",
        "(notes) word (Monday) November 1, 2026",
        "(Monday) notes (notes) November 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(1)), "{line}: the R5-D arm reads clean");
        assert_eq!(
            c.named_weekday_mismatch, None,
            "{line}: the R5-D arm records nothing"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.keep_through,
            Some(nov(1)),
            "{line}: the R5-D arm reads clean"
        );
        assert_eq!(
            c.keep_through_weekday_mismatch, None,
            "{line}: the R5-D arm records nothing"
        );
    }
    // The boundary's other side, held: a weekday
    // group standing mid-line, past a bare word, is
    // in no slot's sequence — the adjudication-5
    // uniform cell (unjudged in every form) is
    // unchanged — and trailing groups followed by
    // more words are not at the trailing slot, so
    // they keep the reading their lone twins keep.
    for line in [
        "notes ([Monday])November 1, 2026",
        "notes ([Monday]) November 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(1)), "{line}: the mid-line cell holds");
        assert_eq!(c.named_weekday_mismatch, None, "{line}");
    }
    r34e_for_twin(
        "November 1, 2026 (Monday) (notes) and more",
        "November 1, 2026 (Monday) and more",
    );
    r34e_keep_twin(
        "November 1, 2026 (Monday) (notes) and more",
        "November 1, 2026 (Monday) and more",
    );
}

#[test]
fn r36c_mixed_pair_wrapper_glued_at_the_leading_slot_is_judged_as_its_spaced_twin() {
    // Round 36 (R36-C, F1 leading arm = red team
    // RT36-3 = verify target (a) extension): the
    // same gate-pattern failure at the leading slot.
    // "([Monday])November 1, 2026" served November 1
    // with no record; its spaced twin refuses with
    // WeekdayMismatch(Monday@2026-11-01), on both
    // routes, for all four mixed pairs. The single-
    // pair leading twins were already judged in both
    // forms (R35-C); the silencing was the mixed
    // wrapper's alone, and the date-slot pass now
    // re-spaces the wrapper's balanced span glued
    // against the month word. Every pair compares
    // the full record (the r34e helpers); the
    // disagreeing headline is stated outright.
    // November 1, 2026 is a Sunday.
    for group in ["([Monday])", "[(Monday)]", "{[Monday]}", "{(Monday)}"] {
        let glued = format!("{group}November 1, 2026");
        let spaced = format!("{group} November 1, 2026");
        r34e_for_twin(&glued, &spaced);
        r34e_keep_twin(&glued, &spaced);
    }
    for group in ["([Sunday])", "[(Sunday)]", "{[Sunday]}", "{(Sunday)}"] {
        let glued = format!("{group}November 1, 2026");
        let spaced = format!("{group} November 1, 2026");
        r34e_for_twin(&glued, &spaced);
        r34e_keep_twin(&glued, &spaced);
    }
    // The doubled same-pair control, unweakened:
    // glued and spaced judge alike, as R35-C pinned
    // the single-pair forms.
    r34e_for_twin("((Monday))November 1, 2026", "((Monday)) November 1, 2026");
    r34e_keep_twin("((Monday))November 1, 2026", "((Monday)) November 1, 2026");
    // Stated outright: the disagreeing glued mixed
    // wrapper is refused with the mismatch recorded,
    // on both routes; the agreeing one reads clean.
    let text = "For Sunday: ([Monday])November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing glued mixed leading weekday is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text = "For Sunday: November 1, 2026\nKeep-through: ([Monday])November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, None);
    let m = c
        .keep_through_weekday_mismatch
        .as_ref()
        .expect("the disagreeing glued mixed leading weekday is recorded on the keep line");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text = "For Sunday: ([Sunday])November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(1)));
    assert_eq!(c.named_weekday_mismatch, None);
}

#[test]
fn r36c_trailing_garnish_in_a_mixed_pair_wrapper_is_judged_as_its_single_pair_twin() {
    // Round 36 (R36-C, F9 = red team RT36-4):
    // "November 1, 2026 ([Monday])" read clean, glued
    // and spaced, all four mixed pairs, both routes;
    // its single-pair twin "(Monday)" is judged
    // (refused with the record), and the doubled
    // same-pair wrappers "((Monday))", "[[Monday]]",
    // "{{Monday}}" trailing are judged too. No
    // glued/spaced divergence — the trailing-garnish
    // check was simply absent for mixed pairs: the
    // trailing pass's candidate scan found only the
    // wrapper's inner pair and set its space inside
    // the wrapper, breaking the token the trailing
    // readers judge. The candidate's contents now
    // shed opening and closing marks of any pair, so
    // the wrapper itself is the candidate. Every
    // pair below compares the mixed line's FULL
    // record against its single-pair twin's (the
    // r34e helpers), agreeing and disagreeing, glued
    // and spaced, on both routes; the disagreeing
    // headline is stated outright. November 1 and
    // November 8, 2026 are Sundays.
    for group in ["([Monday])", "[(Monday)]", "{[Monday]}", "{(Monday)}"] {
        let spaced = format!("November 1, 2026 {group}");
        r34e_for_twin(&spaced, "November 1, 2026 (Monday)");
        let glued = format!("November 1, 2026{group}");
        r34e_for_twin(&glued, "November 1, 2026(Monday)");
        r34e_for_twin(&glued, &spaced);
        let keep_spaced = format!("November 8, 2026 {group}");
        r34e_keep_twin(&keep_spaced, "November 8, 2026 (Monday)");
        let keep_glued = format!("November 8, 2026{group}");
        r34e_keep_twin(&keep_glued, "November 8, 2026(Monday)");
    }
    for group in ["([Sunday])", "[(Sunday)]", "{[Sunday]}", "{(Sunday)}"] {
        let spaced = format!("November 1, 2026 {group}");
        r34e_for_twin(&spaced, "November 1, 2026 (Sunday)");
        let glued = format!("November 1, 2026{group}");
        r34e_for_twin(&glued, "November 1, 2026(Sunday)");
        let keep_spaced = format!("November 8, 2026 {group}");
        r34e_keep_twin(&keep_spaced, "November 8, 2026 (Sunday)");
        let keep_glued = format!("November 8, 2026{group}");
        r34e_keep_twin(&keep_glued, "November 8, 2026(Sunday)");
    }
    // The doubled same-pair controls, unweakened:
    // each still judges as the single-pair twin.
    for group in ["((Monday))", "[[Monday]]", "{{Monday}}"] {
        let spaced = format!("November 1, 2026 {group}");
        r34e_for_twin(&spaced, "November 1, 2026 (Monday)");
        let glued = format!("November 1, 2026{group}");
        r34e_for_twin(&glued, "November 1, 2026(Monday)");
    }
    // Stated outright: the disagreeing mixed
    // trailing garnish is refused with the mismatch
    // recorded, glued and spaced, on both routes;
    // the agreeing one reads clean.
    for line in ["November 1, 2026 ([Monday])", "November 1, 2026([Monday])"] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing mixed trailing weekday is recorded");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
        let keep_line = line.replace("November 1, 2026", "November 8, 2026");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {keep_line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{keep_line}");
        let m = c
            .keep_through_weekday_mismatch
            .as_ref()
            .expect("the disagreeing mixed trailing weekday is recorded on the keep line");
        assert_eq!(m.named, "Monday", "{keep_line}");
        assert_eq!(m.date, nov(8), "{keep_line}");
    }
    let text = "For Sunday: November 1, 2026 ([Sunday])\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(1)));
    assert_eq!(c.named_weekday_mismatch, None);
}

#[test]
fn r35c_garnish_before_an_apostrophe_or_typographic_quote_is_judged_in_both_forms() {
    // Round 35 (R35-C, F7 = red team RT35-5): a
    // disagreeing weekday garnish followed by "'"
    // or "”" was judged in NEITHER form — "November
    // 1, 2026 (Monday)'" and "(Monday)”", glued and
    // spaced alike, read the date clean with no
    // mismatch record. The R34-C peel set (". , ; :
    // ! ? \"") stopped before the apostrophe and the
    // typographic closing quote a phone keyboard
    // produces after a garnish, and the sentence-mark
    // trim sets in the garnish path (`clean`, the
    // trailing-weekday scans, the Sunday-after base
    // scan) stopped at the same place. Those sets
    // learn both marks here, so the garnish is judged
    // exactly as the standing peel marks judge it:
    // a disagreeing one refuses the date and records
    // the mismatch, an agreeing one reads clean, in
    // both forms, in all three pairs, on the For line
    // and the Keep-through line. November 1 and
    // November 8, 2026 are Sundays.
    for mark in ['\'', '\u{201d}'] {
        for (open, close) in [("(", ")"), ("[", "]"), ("{", "}")] {
            let glued_disagree = format!("November 1, 2026{open}Monday{close}{mark}");
            let spaced_disagree = format!("November 1, 2026 {open}Monday{close}{mark}");
            r34c_for_twin(
                &glued_disagree,
                &spaced_disagree,
                None,
                Some(("Monday", nov(1))),
            );
            let glued_agree = format!("November 1, 2026{open}Sunday{close}{mark}");
            let spaced_agree = format!("November 1, 2026 {open}Sunday{close}{mark}");
            r34c_for_twin(&glued_agree, &spaced_agree, Some(nov(1)), None);
            let glued_keep_disagree = format!("November 8, 2026{open}Monday{close}{mark}");
            let spaced_keep_disagree = format!("November 8, 2026 {open}Monday{close}{mark}");
            r34c_keep_twin(
                &glued_keep_disagree,
                &spaced_keep_disagree,
                None,
                Some(("Monday", nov(8))),
            );
            let glued_keep_agree = format!("November 8, 2026{open}Sunday{close}{mark}");
            let spaced_keep_agree = format!("November 8, 2026 {open}Sunday{close}{mark}");
            r34c_keep_twin(&glued_keep_agree, &spaced_keep_agree, Some(nov(8)), None);
        }
        // The mark layered with the standing suffix
        // shapes: before a trailing separator token,
        // doubled, and beside a standing peel mark.
        let glued_sep = format!("November 1, 2026(Monday){mark} *");
        let spaced_sep = format!("November 1, 2026 (Monday){mark} *");
        r34c_for_twin(&glued_sep, &spaced_sep, None, Some(("Monday", nov(1))));
        let doubled = format!("November 1, 2026 (Monday){mark}{mark}");
        let text = format!("For Sunday: {doubled}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{doubled}");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing garnish before doubled marks is recorded");
        assert_eq!(m.named, "Monday", "{doubled}");
        assert_eq!(m.date, nov(1), "{doubled}");
        // A Sunday-after base garnish wearing either
        // mark is judged against its base, as its
        // standing-mark twins are: a disagreeing one
        // yields no date and records the mismatch
        // against the base; an agreeing one resolves.
        let base_disagree = format!("Sunday after November 1, 2026 (Monday){mark}");
        let text = format!("For Sunday: {base_disagree}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{base_disagree}");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing base garnish is recorded");
        assert_eq!(m.named, "Monday", "{base_disagree}");
        assert_eq!(m.date, nov(1), "{base_disagree}");
        let base_agree = format!("Sunday after November 1, 2026 (Sunday){mark}");
        let text = format!("For Sunday: {base_agree}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(8)), "{base_agree}");
        assert_eq!(c.named_weekday_mismatch, None, "{base_agree}");
        // The bare trailing weekday word wearing
        // either mark: its date was already refused
        // in both forms, but the same trim omission
        // silenced the record — the word now names
        // its mismatch as a clean trailing word does,
        // and an agreeing one reads clean.
        let bare_disagree = format!("November 1, 2026 Monday{mark}");
        let text = format!("For Sunday: {bare_disagree}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{bare_disagree}");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing bare trailing weekday is recorded");
        assert_eq!(m.named, "Monday", "{bare_disagree}");
        assert_eq!(m.date, nov(1), "{bare_disagree}");
        let bare_agree = format!("November 1, 2026 Sunday{mark}");
        let text = format!("For Sunday: {bare_agree}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(1)), "{bare_agree}");
        assert_eq!(c.named_weekday_mismatch, None, "{bare_agree}");
    }
}

// ---- Round 35 (R35-F, F6, as adjudicated
// 2026-10-21): malformed groups judge by the
// bare reading of their words. The summary below
// is the step-1 battery probe's own format (the
// red team's summary shape), so a pin here compares
// every field the battery compared.

fn r35f_date(d: &Option<SimpleDate>) -> String {
    match d {
        Some(x) => format!("{}-{:02}-{:02}", x.year, x.month, x.day),
        None => "None".to_string(),
    }
}

fn r35f_summary(c: &Contribution) -> String {
    let wm = c
        .named_weekday_mismatch
        .as_ref()
        .map(|m| format!("{}@{}", m.named, r35f_date(&Some(m.date))));
    let kwm = c
        .keep_through_weekday_mismatch
        .as_ref()
        .map(|m| format!("{}@{}", m.named, r35f_date(&Some(m.date))));
    let parens: Vec<String> = c
        .for_sunday_parenthesized_dates
        .iter()
        .map(|d| r35f_date(&Some(*d)))
        .collect();
    let secs: Vec<String> = c
        .for_sunday_second_dates
        .iter()
        .map(|d| r35f_date(&Some(*d)))
        .collect();
    let ksecs: Vec<String> = c
        .keep_through_second_dates
        .iter()
        .map(|d| r35f_date(&Some(*d)))
        .collect();
    format!(
        "for={} keep={} wm={:?} kwm={:?} inwords={:?} after={:?} paren={} parens={:?} pmis={:?} kmis={:?} sec={} secs={:?} ksec={} ksecs={:?}",
        r35f_date(&c.for_date),
        r35f_date(&c.keep_through),
        wm,
        kwm,
        c.for_sunday_in_words,
        c.for_sunday_after_in_words,
        r35f_date(&c.for_sunday_parenthesized_date),
        parens,
        c.for_sunday_parenthesized_mismatch,
        c.keep_through_parenthesized_mismatch,
        r35f_date(&c.for_sunday_second_date),
        secs,
        r35f_date(&c.keep_through_second_date),
        ksecs,
    )
}

fn r35f_for(line: &str) -> String {
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    r35f_summary(&c)
}

