#[test]
fn r37b_nonleading_group_with_a_trailing_group_in_every_pair() {
    // A mid group beside the phrase with a trailing
    // group standing after it: the core re-read
    // (trailing groups stripped, the mid group still
    // standing in the core) takes the same judgment,
    // so every pair reads as the paren line — silent
    // on the For route, and the Keep-through line
    // stands the trailing group alone.
    for (wrapped, paren) in [
        (
            "notes [November 8, 2026] next Sunday (November 15, 2026)",
            "notes (November 8, 2026) next Sunday (November 15, 2026)",
        ),
        (
            "notes {November 8, 2026} next Sunday (November 15, 2026)",
            "notes (November 8, 2026) next Sunday (November 15, 2026)",
        ),
        (
            "notes [October 25, 2026] next Sunday (November 15, 2026)",
            "notes (October 25, 2026) next Sunday (November 15, 2026)",
        ),
        (
            "notes [November 1, 2026] the Sunday after next Sunday (November 15, 2026)",
            "notes (November 1, 2026) the Sunday after next Sunday (November 15, 2026)",
        ),
    ] {
        r36d_pair(wrapped, paren);
    }
    let text = "For Sunday: November 1, 2026\nKeep-through: notes (November 8, 2026) next Sunday (November 15, 2026)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(
        c.keep_through,
        Some(nov(15)),
        "the keep-through line stands the trailing group"
    );
    assert_eq!(
        c.keep_through_parenthesized_mismatch, None,
        "with no mismatch record from the mid group"
    );
}

#[test]
fn r37b_held_positions_beside_relative_phrases_keep_their_readings() {
    // The held positions, stated outright at their
    // standing readings (witnessed twin-equal by all
    // three lanes); none of these lines moves.
    //
    // A group AFTER the phrase: the For route reads
    // nothing (the prefix already breaks the in-words
    // shape in every pair), and the Keep-through line
    // stands the trailing group.
    for line in [
        "notes next Sunday (November 8, 2026)",
        "notes next Sunday [November 8, 2026]",
        "notes next Sunday {November 8, 2026}",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date on the For route");
        assert_eq!(
            c.for_sunday_in_words, None,
            "{line}: nothing remembered in words"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.keep_through,
            Some(nov(8)),
            "{line}: the keep-through line stands the group after the phrase"
        );
        assert_eq!(
            c.keep_through_second_dates,
            Vec::<SimpleDate>::new(),
            "{line}: no second date on the keep-through route"
        );
    }
    // A group beside a Sunday-after (absolute-base)
    // phrase, in both orders: the phrase resolves
    // November 8 and stands in every pair; a
    // disagreeing trailing group is named on the
    // parenthesized mismatch record.
    for line in [
        "notes (November 8, 2026) Sunday after November 1, 2026",
        "notes [November 8, 2026] Sunday after November 1, 2026",
        "notes {November 8, 2026} Sunday after November 1, 2026",
        "notes Sunday after November 1, 2026 (November 8, 2026)",
        "notes Sunday after November 1, 2026 [November 8, 2026]",
        "notes Sunday after November 1, 2026 {November 8, 2026}",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{line}: the Sunday-after resolution stands"
        );
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: the agreeing group records nothing"
        );
    }
    let text = "For Sunday: notes Sunday after November 1, 2026 [November 15, 2026]\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)), "the resolution stands");
    assert_eq!(
        c.for_sunday_parenthesized_mismatch
            .as_ref()
            .map(|m| m.named),
        Some(nov(15)),
        "the disagreeing trailing group is named on the record"
    );
    // Weekday-garnish and governor groups beside the
    // phrase: silent in every pair.
    for line in [
        "notes (Monday) next Sunday",
        "notes [Monday] next Sunday",
        "notes {Monday} next Sunday",
        "notes (cancelled) next Sunday",
        "notes [cancelled] next Sunday",
        "notes {cancelled} next Sunday",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date");
        assert_eq!(c.for_sunday_in_words, None, "{line}: no memory");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: nothing kept");
    }
    // Stacked AGREEING groups beside the phrase
    // (every group before the phrase carrying the
    // same date): the shared date is adopted in every
    // pair form, the phrase's resolution named as the
    // second date — the red team's a8 reading, held.
    for line in [
        "notes (November 8, 2026) [November 8, 2026] next Sunday",
        "notes [November 8, 2026] (November 8, 2026) next Sunday",
        "notes {November 8, 2026} (November 8, 2026) next Sunday",
        "notes [November 8, 2026] [November 8, 2026] next Sunday",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{line}: the agreeing stack's date stands"
        );
        assert_eq!(
            c.for_sunday_second_dates,
            vec![oct(25)],
            "{line}: the phrase's resolution is the second date"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.keep_through,
            Some(nov(8)),
            "{line}: the keep-through line keeps the agreeing date"
        );
        assert_eq!(
            c.keep_through_second_dates,
            vec![oct(25)],
            "{line}: the resolution is named on the keep-through note"
        );
    }
    // A stacked agreeing group restating the phrase:
    // adopted clean, nothing else named.
    let text =
        "For Sunday: notes [October 25, 2026] [October 25, 2026] next Sunday\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(oct(25)), "the restating stack stands");
    assert_eq!(
        c.for_sunday_second_dates,
        Vec::<SimpleDate>::new(),
        "and names nothing else"
    );
    // Mixed wrappers beside the phrase: the outer
    // paren pair already blocks the plain reading in
    // every form — silent in every pair.
    for line in [
        "notes ([November 8, 2026]) next Sunday",
        "notes ({November 8, 2026}) next Sunday",
        "notes [(November 8, 2026)] next Sunday",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: nothing kept");
    }
}

#[test]
fn r36f_stray_bracket_and_brace_marks_read_as_their_paren_and_bare_twins() {
    // Round 36 (R36-F, F8 = review R36-8): the R35-F
    // stray-mark recovery was paren-only at the head
    // of the line. "(November 1, 2026" and
    // ")November 1, 2026" read as their bare twins,
    // but "[November 1, 2026", "{November 1, 2026",
    // "]November 1, 2026", and "}November 1, 2026"
    // read nothing — the sender's date dropped with
    // no record. The stray closer glued to a word's
    // head is now spaced for all three pairs in
    // `stray_mark_spaced`, as the paren closer has
    // been since round 35, and an unmatched "[" or
    // "{" standing at the head of the line is spaced
    // as its paren twin is. A mark standing after
    // other content keeps its bytes: the R26-C
    // restatement shapes below hold at their
    // standing readings.
    for line in [
        "[November 1, 2026",
        "{November 1, 2026",
        "]November 1, 2026",
        "}November 1, 2026",
        "[ November 1, 2026",
        "{ November 1, 2026",
        "[November 1",
        "{November 1",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(1)),
            "{line}: the stray-marked date reads as its bare twin"
        );
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no weekday record");
        assert_eq!(
            c.for_sunday_second_dates,
            Vec::new(),
            "{line}: nothing else is named"
        );
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: no parenthesized record"
        );
    }
    // Field for field against the paren readings,
    // both routes (the r34e helpers).
    for (marked, paren) in [
        ("[November 1, 2026", "(November 1, 2026"),
        ("{November 1, 2026", "(November 1, 2026"),
        ("]November 1, 2026", ")November 1, 2026"),
        ("}November 1, 2026", ")November 1, 2026"),
        ("[November 1", "(November 1"),
        ("{November 1", "(November 1"),
    ] {
        r34e_for_twin(marked, paren);
        r34e_keep_twin(marked, paren);
    }
    // The keep-through line standing alone (no For
    // Sunday line at all): the same recovery, at the
    // keep route's own fallback.
    for (marked, paren) in [
        ("[November 29, 2026", "(November 29, 2026"),
        ("{November 29, 2026", "(November 29, 2026"),
        ("]November 29, 2026", ")November 29, 2026"),
        ("}November 29, 2026", ")November 29, 2026"),
    ] {
        let text = format!("Keep-through: {marked}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.keep_through,
            Some(nov(29)),
            "{marked}: the stray-marked keep date reads as its bare twin"
        );
        let paren_text = format!("Keep-through: {paren}\n\n## Announcement\n\nHi.\n");
        let p = parse_contribution(&paren_text, today()).expect("parses");
        assert_eq!(
            c.keep_through, p.keep_through,
            "{marked}: the keep twin's date"
        );
        assert_eq!(
            c.keep_through_second_dates, p.keep_through_second_dates,
            "{marked}: the keep twin's named dates"
        );
    }
    // Holds: an unmatched bracket standing AFTER
    // other content keeps the R26-C reading — the
    // restatement mask binds it beside its governed
    // sibling — and a stray closer at a word's tail
    // MID-LINE keeps the R35-F hold. Neither is this
    // ruling's surface. (Round 37, R37-F, F10: the
    // two line-END tail forms that stood here —
    // "November 1, 2026]" and "November 1, 2026}" —
    // are F10's trailing-stray forms and now read
    // November 1, as their wrapped twins do; they
    // are pinned at their new reading in
    // `r37f_stray_closer_recovery_covers_doubled_head_trailing_and_bare_nested_day_group`.
    // The mid-line tail form below is not F10's
    // trailing form and its hold is unmoved.)
    for line in [
        "(November 1, cancelled) [November 1",
        "(November 1, cancelled) {November 1",
        "(November 1, cancelled) [our choir November 1",
        "November 1], 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: the standing hold reads no date");
        assert_eq!(
            c.for_sunday_second_dates,
            Vec::new(),
            "{line}: the standing hold names nothing"
        );
    }
}

#[test]
fn r36f_in_words_memory_treats_a_stray_bracket_as_its_paren_twin() {
    // Round 36 (R36-F, F11 = review R36-9): on the
    // audited tree "[next Sunday" was remembered in
    // words verbatim — the stray bracket repeated
    // back as part of the sender's phrase — while
    // "(next Sunday" was not remembered at all.
    // R36-D's leading-group gate (F4) has since
    // brought the bracket and brace forms under the
    // same gate the paren form stands under, and on
    // this tree the twins already judge alike: a
    // stray opener at the head of the line is
    // remembered in NEITHER pair. This pin locks
    // that parity on the in-words surfaces, and
    // states the agreeing forms beside it: a stray
    // CLOSER at the head, and a stray opener behind
    // the garnish "on", are remembered verbatim in
    // every pair alike — each pair repeats the
    // sender's own mark, which is the standing
    // treatment, not a divergence.
    for line in [
        "(next Sunday",
        "[next Sunday",
        "{next Sunday",
        "(this Sunday",
        "[this Sunday",
        "{this Sunday",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_sunday_in_words, None,
            "{line}: a stray opener at the head is not remembered, in any pair"
        );
    }
    r34e_for_twin("[next Sunday", "(next Sunday");
    r34e_for_twin("{next Sunday", "(next Sunday");
    r34e_for_twin("[this Sunday", "(this Sunday");
    for line in [
        "(the Sunday after next Sunday",
        "[the Sunday after next Sunday",
        "{the Sunday after next Sunday",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_sunday_after_in_words, None,
            "{line}: the after-phrase behind a stray opener is not remembered, in any pair"
        );
    }
    r34e_for_twin(
        "[the Sunday after next Sunday",
        "(the Sunday after next Sunday",
    );
    // The agreeing verbatim forms, stated outright
    // per pair: the remembered words are the
    // sender's own, stray mark included, in every
    // pair alike.
    for (line, remembered) in [
        (")next Sunday", ")next Sunday"),
        ("]next Sunday", "]next Sunday"),
        ("}next Sunday", "}next Sunday"),
        ("on (next Sunday", "on (next Sunday"),
        ("on [next Sunday", "on [next Sunday"),
        ("on {next Sunday", "on {next Sunday"),
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_sunday_in_words.as_deref(),
            Some(remembered),
            "{line}: remembered verbatim, as in every pair"
        );
    }
}

#[test]
fn r36f_sunday_after_shape_word_wearing_sentence_marks_reads_as_its_controls() {
    // Round 36 (R36-F, F12 = review R36-10): the
    // Sunday-after shape word wearing "!", "?", or
    // quotes read nothing at all — no date, no
    // record — while wearing ":" or ";" it read.
    // `sunday_after_outcome`'s shape trim judged
    // only the wrapper pairs, "," and ".", and
    // `weekday_word`'s trailing trim between them
    // covered ":" and ";" but not the other three
    // marks. The shape trim now learns the sentence
    // marks, on both words of the shape. November 1,
    // 2026 is a Sunday; the Sunday after it is
    // November 8, 2026.
    for shape in [
        "Sunday!",
        "Sunday?",
        "\"Sunday\"",
        "'Sunday'",
        // The controls, at their standing readings.
        "Sunday:",
        "Sunday;",
        "Sunday.",
        "Sunday,",
        "Sunday",
    ] {
        let line = format!("{shape} after November 1, 2026");
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{line}: the shape word wearing its mark reads the Sunday after"
        );
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no weekday record");
        assert_eq!(
            c.for_sunday_second_dates,
            Vec::new(),
            "{line}: the base is consumed by its phrase, not named"
        );
        r34e_for_twin(&line, "Sunday: after November 1, 2026");
        r34e_keep_twin(&line, "Sunday: after November 1, 2026");
    }
    // The garnish forms of the shape read the same.
    for line in [
        "the Sunday! after November 1, 2026",
        "on Sunday? after November 1, 2026",
        "the \"Sunday\" after November 1, 2026",
        "on 'Sunday' after November 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{line}: the garnished shape reads the Sunday after"
        );
    }
    // The shape's second word wearing a mark reads
    // as its bare twin does.
    for line in [
        "Sunday after! November 1, 2026",
        "Sunday after? November 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{line}: the marked second word reads the Sunday after"
        );
        r34e_for_twin(line, "Sunday after November 1, 2026");
    }
    // A disagreeing base weekday under a marked
    // shape word records the mismatch, as the bare
    // shape's does — the phrase is refused, not
    // collapsed to its base.
    let line = "Sunday! after Monday November 1, 2026";
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(c.for_date, None, "{line}: the disagreeing base refuses");
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the mismatch is recorded");
    assert_eq!(m.named, "Monday", "{line}: the record names the weekday");
    assert_eq!(m.date, nov(1), "{line}: the record names the base date");
    r34e_for_twin(line, "Sunday after Monday November 1, 2026");
    // Inside a group the marked shape forms its
    // phrase too: the group's resolution is the
    // line's date and the core is named beside it,
    // exactly as the bare group form reads — no
    // phantom mismatch naming the resolution.
    let line = "November 15, 2026 (Sunday! after November 1, 2026)";
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(
        c.for_date,
        Some(nov(8)),
        "{line}: the group's resolution is the line's date"
    );
    assert_eq!(
        c.for_sunday_second_dates,
        vec![nov(15)],
        "{line}: the core is named as the second date"
    );
    assert_eq!(
        c.for_sunday_parenthesized_mismatch, None,
        "{line}: no phantom mismatch stands"
    );
    r34e_for_twin(line, "November 15, 2026 (Sunday after November 1, 2026)");
}

#[test]
fn r37e_curly_quoted_governor_inside_a_group_governs_as_its_straight_and_bare_twins() {
    // Round 37 (R37-E, F2 MAJOR governor arm =
    // verify V3 / review R37-R2 / red team RT37-3;
    // F4 MAJOR = review R37-R5): a curly-quoted
    // governing word inside a group escaped
    // judgment where its straight-quoted and bare
    // twins govern — "(November 8, 2026
    // “cancelled”)" adopted November 8 on both
    // routes. The group cleaners' trim sets held
    // no curly quotes at all (`clean_group_word`,
    // reached via `group_token`), and the
    // typographic closing quotes U+201D/U+2019
    // were missing from the trailing trim sets at
    // `is_bracketed_token`, `group_token`,
    // `clean_group_word`, and
    // `bracketed_weekday_word`, so a governor
    // wearing one escaped the same way
    // ("[cancelled]”" and its siblings adopted the
    // cancelled date). The adjudicated reading is
    // parity with the straight-quoted twins at
    // every site. Every pair below compares the
    // curly form's FULL record against its
    // straight-quoted and bare twins' (the r34e
    // helpers), on the For line and the
    // Keep-through line; the headline forms are
    // stated outright after. November 1 and
    // November 8, 2026 are Sundays.
    for curly in [
        "(November 8, 2026 \u{201c}cancelled\u{201d})",
        "(November 8, 2026 [\u{201c}cancelled\u{201d}])",
        "(November 8, 2026 \u{2018}cancelled\u{2019})",
        "(November 8, 2026 [\u{2018}cancelled\u{2019}])",
    ] {
        r34e_for_twin(curly, "(November 8, 2026 \"cancelled\")");
        r34e_keep_twin(curly, "(November 8, 2026 \"cancelled\")");
        r34e_for_twin(curly, "(November 8, 2026 cancelled)");
        r34e_keep_twin(curly, "(November 8, 2026 cancelled)");
    }
    // The F4 adoption forms: a typographic closing
    // quote trailing the wrapped governor, inside
    // the pair, or trailing a bare in-group
    // governor — each against its ASCII-mark and
    // paren controls, which govern.
    for curly in [
        "(November 8, 2026 [cancelled]\u{201d})",
        "(November 8, 2026 {cancelled}\u{201d})",
        "(November 8, 2026 [cancelled\u{201d}])",
        "(November 8, 2026 [cancelled]\u{2019})",
        "(November 8, 2026 cancelled\u{201d})",
        "(November 8, 2026 cancelled\u{2019})",
    ] {
        r34e_for_twin(curly, "(November 8, 2026 [cancelled]!)");
        r34e_keep_twin(curly, "(November 8, 2026 [cancelled]!)");
        r34e_for_twin(curly, "(November 8, 2026 cancelled)");
        r34e_keep_twin(curly, "(November 8, 2026 cancelled)");
    }
    // The review lane's unwitnessed observation 3,
    // witnessed pre-fix in
    // `r37e-openonly-prefix.log`: a curly OPENING
    // quote as the governor's only curly mark
    // escaped in every form (bracketed, bare
    // in-group, and the stray-closer form), while
    // every straight open-only twin governed. They
    // land under this fix, at the same parity.
    for curly in [
        "(November 8, 2026 [\u{2018}cancelled])",
        "(November 8, 2026 [\u{201c}cancelled])",
        "(November 8, 2026 \u{2018}cancelled)",
        "(November 8, 2026 \u{201c}cancelled)",
        "(November 8, 2026 \u{201c}cancelled\u{201d}])",
        "(November 8, 2026 \u{2018}cancelled\u{2019}])",
    ] {
        r34e_for_twin(curly, "(November 8, 2026 ['cancelled])");
        r34e_keep_twin(curly, "(November 8, 2026 ['cancelled])");
        r34e_for_twin(curly, "(November 8, 2026 cancelled)");
        r34e_keep_twin(curly, "(November 8, 2026 cancelled)");
    }
    // Stated outright: the headline governor forms
    // govern — no date reads, on either route.
    for line in [
        "(November 8, 2026 \u{201c}cancelled\u{201d})",
        "(November 8, 2026 [\u{201c}cancelled\u{201d}])",
        "(November 8, 2026 [cancelled]\u{201d})",
        "(November 8, 2026 [\u{2018}cancelled])",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: the governed date reads nothing");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.keep_through, None,
            "{line}: the governed date reads nothing on the keep line"
        );
    }
    // The F4 trailing-group phantom form: the
    // ungoverned group date was named against the
    // line's date in a phantom parenthesized
    // mismatch. Governed, the group contributes
    // nothing and the line reads exactly as its
    // paren control reads.
    let curly = "November 15, 2026 (November 8, 2026 [cancelled]\u{201d})";
    r34e_for_twin(
        curly,
        "November 15, 2026 (November 8, 2026 (cancelled)\u{201d})",
    );
    r34e_keep_twin(
        curly,
        "November 15, 2026 (November 8, 2026 (cancelled)\u{201d})",
    );
    let text = format!("For Sunday: {curly}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(15)), "{curly}: the line's date reads");
    assert_eq!(
        c.for_sunday_parenthesized_mismatch, None,
        "{curly}: no phantom mismatch stands"
    );
}

#[test]
fn r37e_curly_quoted_sunday_after_phrase_forms_where_its_straight_twin_forms() {
    // Round 37 (R37-E, F2 MAJOR phrase arms +
    // F3 MINOR shape arms): a curly-quoted
    // Sunday-after shape word never formed its
    // phrase where the straight-quoted phrase
    // forms — inside a group the base stood as a
    // plain signal and was recorded against the
    // resolution (the group canary's phantom
    // ParenthesizedDateMismatch), whole-line group
    // forms collapsed to the base, a wrapped
    // base-leading weekday collapsed the phrase the
    // same way, a curly base trailing garnish was
    // served without the refusal record every twin
    // records, and whole-line the shape word, the
    // second word, and an unwrapped disagreeing
    // base-leading weekday all read silence. A
    // trim-only shape is the round-36 reverted
    // anti-pattern; the adjudicated reading is
    // that the phrase FORMS wherever the
    // straight-quoted phrase forms, including
    // inside groups. The sites are the full set
    // the lanes mapped: `clean_group_word` /
    // `group_token` (the shared cleaning every
    // gate below reads), the
    // `dates_inside_group_signals` gate,
    // `sunday_after_phrase_run`'s token cleaning,
    // `sunday_after_outcome`'s shape trims, and
    // `sunday_after_base` (its lead-weekday path
    // and its trailing trim, which held U+201D but
    // not U+201C). November 1, 2026 is a Sunday;
    // the Sunday after it is November 8.
    // The group canary, disagreeing and agreeing:
    // the resolution is the line's date, the core
    // named beside it, and no phantom record —
    // field-for-field the straight and bare twins.
    for curly in [
        "November 15, 2026 (\u{201c}Sunday\u{201d} after November 1, 2026)",
        "November 15, 2026 ({\u{201c}Sunday\u{201d}} after November 1, 2026)",
    ] {
        r34e_for_twin(
            curly,
            "November 15, 2026 (\"Sunday\" after November 1, 2026)",
        );
        r34e_keep_twin(
            curly,
            "November 15, 2026 (\"Sunday\" after November 1, 2026)",
        );
        r34e_for_twin(curly, "November 15, 2026 (Sunday after November 1, 2026)");
        r34e_keep_twin(curly, "November 15, 2026 (Sunday after November 1, 2026)");
    }
    let line = "November 15, 2026 (\u{201c}Sunday\u{201d} after November 1, 2026)";
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)), "{line}: the resolution reads");
    assert_eq!(
        c.for_sunday_second_dates,
        vec![nov(15)],
        "{line}: the core is named as the second date"
    );
    assert_eq!(
        c.for_sunday_parenthesized_mismatch, None,
        "{line}: no phantom mismatch stands"
    );
    let line = "November 8, 2026 (\u{201c}Sunday\u{201d} after November 1, 2026)";
    r34e_for_twin(line, "November 8, 2026 (\"Sunday\" after November 1, 2026)");
    r34e_keep_twin(line, "November 8, 2026 (\"Sunday\" after November 1, 2026)");
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(
        c.for_date,
        Some(nov(8)),
        "{line}: the agreeing resolution reads"
    );
    assert_eq!(
        c.for_sunday_parenthesized_mismatch, None,
        "{line}: no phantom mismatch stands on agreeing dates"
    );
    // The collapse forms: the whole phrase inside a
    // group of any pair, and the phrase standing in
    // a trailing group, resolve to November 8 —
    // never to the base.
    for curly in [
        "(\u{201c}Sunday\u{201d} after November 1, 2026)",
        "[\u{201c}Sunday\u{201d} after November 1, 2026]",
        "{\u{201c}Sunday\u{201d} after November 1, 2026}",
        "November 8, 2026 [\u{201c}Sunday\u{201d} after November 1, 2026]",
        "November 8, 2026 {\u{201c}Sunday\u{201d} after November 1, 2026}",
    ] {
        let bare = curly.replace(['\u{201c}', '\u{201d}'], "");
        r34e_for_twin(curly, &bare);
        r34e_keep_twin(curly, &bare);
        let text = format!("For Sunday: {curly}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{curly}: the phrase resolves, never collapses to its base"
        );
    }
    // The wrapped base-leading weekday: agreeing
    // reads the resolution as its unwrapped twin
    // does; disagreeing is refused with the record
    // — stated outright, because the record names
    // the sender's word verbatim, curly quotes
    // included, exactly as the straight twin's
    // record names "\"Monday\"" (the verbatim
    // naming itself is R37-F's F11 family and is
    // unchanged here).
    r34e_for_twin(
        "Sunday after (\u{201c}Sunday\u{201d}) November 1, 2026",
        "Sunday after (Sunday) November 1, 2026",
    );
    r34e_keep_twin(
        "Sunday after (\u{201c}Sunday\u{201d}) November 1, 2026",
        "Sunday after (Sunday) November 1, 2026",
    );
    for line in [
        "Sunday after (\u{201c}Monday\u{201d}) November 1, 2026",
        "(Sunday after \u{201c}Monday\u{201d} November 1, 2026)",
        "November 15, 2026 (Sunday after \u{201c}Monday\u{201d} November 1, 2026)",
        "Sunday after \u{201c}Monday\u{201d} November 1, 2026",
        "Sunday after on \u{201c}Monday\u{201d} November 1, 2026",
        "Sunday after \u{2018}Monday\u{2019} November 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: the disagreeing base refuses");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the mismatch is recorded, not lost");
        let named = if line.contains('\u{2018}') {
            "\u{2018}Monday\u{2019}"
        } else {
            "\u{201c}Monday\u{201d}"
        };
        assert_eq!(m.named, named, "{line}: the record names the sender's word");
        assert_eq!(m.date, nov(1), "{line}: the record names the base date");
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: the refusal carries no parenthesized record"
        );
    }
    // The agreeing unwrapped base-leading arm was
    // already at parity and stays: it reads the
    // resolution.
    r34e_for_twin(
        "Sunday after \u{201c}Sunday\u{201d} November 1, 2026",
        "Sunday after \"Sunday\" November 1, 2026",
    );
    r34e_keep_twin(
        "Sunday after \u{201c}Sunday\u{201d} November 1, 2026",
        "Sunday after \"Sunday\" November 1, 2026",
    );
    // The base trailing garnish: a disagreeing
    // curly garnish refuses with the record, as
    // bare, straight, and paren twins do — the
    // record's named word is the cleaned weekday
    // at this site, so the full records are the
    // twins' — and an agreeing one lets the phrase
    // resolve.
    for curly in [
        "Sunday after November 1, 2026 \u{201c}Monday\u{201d}",
        "Sunday after November 1, 2026 \u{2018}Monday\u{2019}",
    ] {
        r34e_for_twin(curly, "Sunday after November 1, 2026 \"Monday\"");
        r34e_keep_twin(curly, "Sunday after November 1, 2026 \"Monday\"");
        r34e_for_twin(curly, "Sunday after November 1, 2026 Monday");
        r34e_keep_twin(curly, "Sunday after November 1, 2026 Monday");
    }
    r34e_for_twin(
        "Sunday after November 1, 2026 \u{201c}Sunday\u{201d}",
        "Sunday after November 1, 2026 \"Sunday\"",
    );
    r34e_keep_twin(
        "Sunday after November 1, 2026 \u{201c}Sunday\u{201d}",
        "Sunday after November 1, 2026 \"Sunday\"",
    );
    // The whole-line shape arms (F3): the shape
    // word in either curly pair, open-quote-only,
    // close-quote-only, behind "the", behind "on",
    // the mixed-quote forms, and over a
    // disagreeing base date — each forms the
    // phrase exactly as its straight and bare
    // twins do. The shape's second word wearing
    // the pair forms it too.
    for curly in [
        "\u{201c}Sunday\u{201d} after November 1, 2026",
        "\u{2018}Sunday\u{2019} after November 1, 2026",
        "\u{201c}Sunday after November 1, 2026",
        "Sunday\u{201d} after November 1, 2026",
        "the \u{201c}Sunday\u{201d} after November 1, 2026",
        "on \u{201c}Sunday\u{201d} after November 1, 2026",
        "\u{201c}Sunday\" after November 1, 2026",
        "\"Sunday\u{201d} after November 1, 2026",
        "\u{201c}Sunday\u{201d} after November 2, 2026",
        "Sunday \u{201c}after\u{201d} November 1, 2026",
    ] {
        let text = format!("For Sunday: {curly}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{curly}: the curly shape forms its phrase"
        );
        assert_eq!(
            c.for_sunday_second_dates,
            Vec::new(),
            "{curly}: the base is consumed by its phrase, not named"
        );
    }
    for (curly, straight) in [
        (
            "\u{201c}Sunday\u{201d} after November 1, 2026",
            "\"Sunday\" after November 1, 2026",
        ),
        (
            "Sunday \u{201c}after\u{201d} November 1, 2026",
            "Sunday \"after\" November 1, 2026",
        ),
    ] {
        r34e_for_twin(curly, straight);
        r34e_keep_twin(curly, straight);
        r34e_for_twin(curly, "Sunday after November 1, 2026");
        r34e_keep_twin(curly, "Sunday after November 1, 2026");
    }
    // The behind-"on" BASE forms are silent in
    // curly, straight, and bare alike — no
    // divergence, and this fix does not move them:
    // a base date standing behind a bare "on" (with
    // no weekday after it) is no shape's base.
    for line in [
        "\u{201c}Sunday\u{201d} after on November 1, 2026",
        "\"Sunday\" after on November 1, 2026",
        "Sunday after on November 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: the after-on base stays silent");
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no record stands");
    }
}

#[test]
fn r37e_curly_quoted_framing_trailing_garnish_and_memory_read_as_their_twins() {
    // Round 37 (R37-E, F3 MINOR framing / trailing
    // / memory arms + F4's wrapped base-leading
    // collapse): curly-quoted words at the line's
    // own slots read nothing where their straight
    // and bare twins read — a line-head framing
    // weekday was dropped in both its arms (the
    // disagreeing one's record lost, the agreeing
    // one's correct date dropped entirely), a
    // plain trailing garnish silenced the line, a
    // relative phrase wearing curly quotes was not
    // remembered, and a wrapped base-leading
    // weekday wearing a typographic closing quote
    // ("[Monday]”") collapsed its phrase to the
    // base. The framing readers' shared cleaning
    // (`clean` in composition.rs) and the trailing
    // garnish trim in `date_line_inner` held
    // U+201D only, and the relative-phrase memory
    // reader judges the shared cleaning
    // (`group_token`), which held no curly quotes.
    // November 1, 2026 is a Sunday.
    // Line-head framing, disagreeing and agreeing,
    // plain and behind "on", in both curly pairs:
    // the full records are the straight twins'
    // (the framing record names the cleaned
    // weekday at this site).
    for curly in [
        "\u{201c}Monday\u{201d} November 1, 2026",
        "on \u{201c}Monday\u{201d} November 1, 2026",
        "\u{2018}Monday\u{2019} November 1, 2026",
        "\u{201c}Sunday\u{201d} November 1, 2026",
    ] {
        let straight = curly
            .replace(['\u{201c}', '\u{201d}'], "\"")
            .replace(['\u{2018}', '\u{2019}'], "'");
        r34e_for_twin(curly, &straight);
        r34e_keep_twin(curly, &straight);
    }
    let line = "\u{201c}Monday\u{201d} November 1, 2026";
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(c.for_date, None, "{line}: the disagreeing framing refuses");
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the framing mismatch is recorded, not lost");
    assert_eq!(m.named, "Monday", "{line}");
    assert_eq!(m.date, nov(1), "{line}");
    let line = "\u{201c}Sunday\u{201d} November 1, 2026";
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(
        c.for_date,
        Some(nov(1)),
        "{line}: the agreeing framing's date is served, not dropped"
    );
    assert_eq!(c.named_weekday_mismatch, None, "{line}: no record");
    // Plain trailing garnish: the disagreeing
    // curly garnish refuses with the record, the
    // agreeing one is consumed and the date reads
    // — the straight twins' readings, outright.
    let line = "November 1, 2026 \u{201c}Monday\u{201d}";
    r34e_for_twin(line, "November 1, 2026 \"Monday\"");
    r34e_keep_twin(line, "November 1, 2026 \"Monday\"");
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(c.for_date, None, "{line}: the disagreeing garnish refuses");
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the garnish mismatch is recorded, not lost");
    assert_eq!(m.named, "Monday", "{line}");
    assert_eq!(m.date, nov(1), "{line}");
    let line = "November 1, 2026 \u{201c}Sunday\u{201d}";
    r34e_for_twin(line, "November 1, 2026 \"Sunday\"");
    r34e_keep_twin(line, "November 1, 2026 \"Sunday\"");
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(
        c.for_date,
        Some(nov(1)),
        "{line}: the agreeing garnish reads"
    );
    assert_eq!(c.named_weekday_mismatch, None, "{line}: no record");
    // Relative-phrase memory: the curly forms are
    // remembered, in the sender's own words
    // verbatim — curly quotes included, exactly as
    // the straight form is remembered with its
    // straight quotes. Stated outright, because
    // the remembered text is the sender's own and
    // differs from the twins' by the quote
    // characters themselves; the straight and bare
    // controls stand unchanged beside them.
    for line in [
        "\u{201c}next Sunday\u{201d}",
        "next \u{201c}Sunday\u{201d}",
        "\u{2018}next Sunday\u{2019}",
        "\"next Sunday\"",
        "next \"Sunday\"",
        "next Sunday",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_sunday_in_words.as_deref(),
            Some(line),
            "{line}: the relative phrase is remembered verbatim"
        );
        assert_eq!(c.for_date, None, "{line}: a words-only line reads no date");
    }
    // F4's wrapped base-leading collapse: the
    // phrase is refused with the record, never
    // collapsed to its base. Stated outright.
    // (Round 37, R37-F, F11: when this pin landed
    // under R37-E the record named the wrapped word
    // verbatim, wrapper residue included —
    // "Monday]”" — and the pin recorded that as
    // the standing F11 shape, F11 being this
    // batch's finding. The named values below are
    // F11's cleaned weekday, "Monday", on every
    // form; the refusal, the record's presence, and
    // its base date are exactly as R37-E pinned
    // them. The verbatim quoted-word records above
    // ("“Monday”" at the base-leading site) are the
    // boundary's other side and are unmoved — see
    // `r37f_base_leading_mismatch_record_names_the_weekday_without_wrapper_or_mark_residue`.)
    for (line, named) in [
        ("Sunday after [Monday]\u{201d} November 1, 2026", "Monday"),
        ("Sunday after [Monday]\u{2019} November 1, 2026", "Monday"),
        ("Sunday after {Monday}\u{2019} November 1, 2026", "Monday"),
        ("Sunday after [Monday]! November 1, 2026", "Monday"),
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: the wrapped weekday refuses");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the mismatch is recorded, not collapsed away");
        assert_eq!(m.named, named, "{line}");
        assert_eq!(m.date, nov(1), "{line}");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: the keep route refuses too");
        let m = c
            .keep_through_weekday_mismatch
            .as_ref()
            .expect("the mismatch is recorded on the keep route");
        assert_eq!(m.named, named, "{line}");
        assert_eq!(m.date, nov(1), "{line}");
    }
    // Controls, unchanged: a whole date wearing
    // quotes is silent in the curly form exactly
    // as in the straight form (no twin diverges —
    // the bare form's reading is the flexible
    // reader's, and neither quoted form has ever
    // had it), and the straight-quote controls of
    // every arm above stand at their standing
    // readings.
    r34e_for_twin("\u{201c}November 8, 2026\u{201d}", "\"November 8, 2026\"");
    r34e_keep_twin("\u{201c}November 8, 2026\u{201d}", "\"November 8, 2026\"");
    let text = "For Sunday: \"Sunday\" after November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    let text = "For Sunday: \"Monday\" November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the straight control's record stands");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
}

#[test]
fn r37f_bare_month_and_day_sentence_marks_read_as_their_clean_and_grouped_twins() {
    // Round 37 (R37-F, F9 MINOR = red team RT37-7):
    // a sentence mark glued to a bare month word or
    // day number killed the date silently —
    // "November! 1, 2026", "November? 1, 2026",
    // "November: 1, 2026", "November 1!, 2026", and
    // "November 1?, 2026" all read nothing, on both
    // routes, while the grouped twins
    // "(November! 8, 2026)" and "[November! 8, 2026]"
    // read November 8 (analyze37.log families
    // s-mark-month / s-mark-day / s-mark-group-month).
    // The reading exists in the grouped path — the
    // group cleaners shed the mark at the word's
    // edge — and only the bare path lost it. The
    // same-family completions at the same two slots
    // ("November; 1, 2026", "November 1:, 2026",
    // "November 1;, 2026") were witnessed reading
    // nothing on the pre-fix tree too
    // (r37f-prefix-probe.log), and the grouped
    // readers shed ";" and the day-slot ":" at those
    // edges by the same trim, so they land with the
    // family. The adjudicated reading: a sentence
    // mark standing against a month word or a day
    // number is garnish the grouped readers already
    // shed, and the bare path reads as its grouped
    // twin does. November 1, 2026 is a Sunday.
    for line in [
        "November! 1, 2026",
        "November? 1, 2026",
        "November: 1, 2026",
        "November; 1, 2026",
        "November 1!, 2026",
        "November 1?, 2026",
        "November 1:, 2026",
        "November 1;, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(1)),
            "{line}: the marked bare date reads as its clean twin"
        );
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no weekday record");
        assert_eq!(
            c.for_sunday_second_dates,
            Vec::new(),
            "{line}: nothing else is named"
        );
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: no parenthesized record"
        );
        // Field for field against the clean reading,
        // both routes (the r34e helpers).
        r34e_for_twin(line, "November 1, 2026");
        r34e_keep_twin(line, "November 1, 2026");
    }
    // The grouped controls, unchanged: the reading
    // the bare path now takes stood here all along.
    for line in ["(November! 8, 2026)", "[November! 8, 2026]"] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{line}: the grouped control reads November 8"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.keep_through,
            Some(nov(8)),
            "{line}: the grouped control keeps November 8"
        );
    }
}

#[test]
fn r37f_stray_closer_recovery_covers_doubled_head_trailing_and_bare_nested_day_group() {
    // Round 37 (R37-F, F10 MINOR = red team RT37-8):
    // three stray-closer cells past R36-F's recovery
    // dropped the date with no record, while their
    // twins read (analyze37.log families
    // s-stray-close / s-extra-close / s-nested-date):
    // a doubled head stray ("))November 1, 2026" —
    // the single strays ")", "]", "}" read
    // November 1), a trailing stray at the line's
    // end ("November 1, 2026)", also "]" and "}" —
    // the wrapped "(November 1, 2026))" reads), and
    // a bare nested day group ("November (8), 2026"
    // — the wrapped twins "(November (8), 2026)",
    // "[November [8], 2026]", and "(November [8],
    // 2026)" read November 8). The adjudicated
    // reading: R36-F's stray recovery covers all
    // three exactly as their wrapped twins read.
    // November 1 and November 8, 2026 are Sundays.
    for line in [
        "))November 1, 2026",
        "]]November 1, 2026",
        "}}November 1, 2026",
        ")]November 1, 2026",
        ")))November 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(1)),
            "{line}: the doubled head stray reads as its single-stray twin"
        );
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no weekday record");
        assert_eq!(
            c.for_sunday_second_dates,
            Vec::new(),
            "{line}: nothing else is named"
        );
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: no parenthesized record"
        );
        r34e_for_twin(line, ")November 1, 2026");
        r34e_keep_twin(line, ")November 1, 2026");
        r34e_for_twin(line, "November 1, 2026");
        r34e_keep_twin(line, "November 1, 2026");
    }
    for line in [
        "November 1, 2026)",
        "November 1, 2026]",
        "November 1, 2026}",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(1)),
            "{line}: the trailing stray reads as its wrapped twin"
        );
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no weekday record");
        assert_eq!(
            c.for_sunday_second_dates,
            Vec::new(),
            "{line}: nothing else is named"
        );
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: no parenthesized record"
        );
        r34e_for_twin(line, "November 1, 2026");
        r34e_keep_twin(line, "November 1, 2026");
    }
    for line in ["November (8), 2026", "November [8], 2026"] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{line}: the bare nested day group reads as its wrapped twin"
        );
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no weekday record");
        assert_eq!(
            c.for_sunday_second_dates,
            Vec::new(),
            "{line}: nothing else is named"
        );
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: no parenthesized record — the group is the day, not garnish"
        );
        r34e_for_twin(line, "November 8, 2026");
        r34e_keep_twin(line, "November 8, 2026");
    }
    // Controls, unchanged: the single head strays
    // (R36-F's pins, restated), the wrapped forms
    // with an extra closer, and the wrapped nested
    // day groups all stand at their standing
    // readings.
    for (line, want) in [
        (")November 1, 2026", nov(1)),
        ("]November 1, 2026", nov(1)),
        ("}November 1, 2026", nov(1)),
        ("(November 1, 2026))", nov(1)),
        ("(November (8), 2026)", nov(8)),
        ("[November [8], 2026]", nov(8)),
        ("(November [8], 2026)", nov(8)),
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(want), "{line}: the control stands");
    }
    // The standing hold beside the family, unmoved:
    // a stray closer at a day number's tail MID-LINE
    // is not the trailing form — it keeps the R35-F
    // hold and reads nothing.
    let line = "November 1], 2026";
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(c.for_date, None, "{line}: the mid-line tail hold stands");
    assert_eq!(
        c.for_sunday_second_dates,
        Vec::new(),
        "{line}: the hold names nothing"
    );
}

#[test]
fn r37f_base_leading_mismatch_record_names_the_weekday_without_wrapper_or_mark_residue() {
    // Round 37 (R37-F, F11 MINOR = review R37-R8):
    // at the Sunday-after base's leading slot the
    // refusal was correct in every form, but the
    // mismatch record — the weekday the Check
    // surface quotes back to the sender — named the
    // wrapped or marked word verbatim, residue
    // included: "Sunday after [Monday]! November 1,
    // 2026" recorded "Monday]!", "{Monday}?" recorded
    // "Monday}?", "(Monday)!" recorded "Monday)!",
    // and the bare "Monday!" recorded "Monday!"
    // (add38-37.log). Site: `sunday_after_base` built
    // the named string with an edge trim of
    // "()[]{},." only — the sentence marks are
    // absent, and the trim cannot reach a closing
    // bracket past a trailing mark (or past a
    // trailing typographic quote: "[Monday]”"
    // recorded "Monday]”"). The adjudicated reading:
    // the named string at this site is the cleaned
    // weekday — wrapper and sentence-mark residue
    // shed — in every form whose twin names it
    // clean.
    //
    // THE BOUNDARY, stated outright: a weekday
    // wearing only a quote pair — straight
    // ("\"Monday\"") or curly ("“Monday”"), bare or
    // standing inside a shed wrapper — names the
    // sender's quoted word VERBATIM at this site.
    // That is the standing twin behavior R37-E
    // pinned stated outright, it is not residue, and
    // it does not move here. What sheds is the
    // wrapper pair (brackets, braces, parens) and
    // the sentence marks standing against the word,
    // in either order. November 1, 2026 is a Sunday;
    // the Sunday after it is November 8.
    for (line, named) in [
        ("Sunday after [Monday]! November 1, 2026", "Monday"),
        ("Sunday after {Monday}? November 1, 2026", "Monday"),
        ("Sunday after (Monday)! November 1, 2026", "Monday"),
        ("Sunday after Monday! November 1, 2026", "Monday"),
        ("Sunday after [Monday]\u{201d} November 1, 2026", "Monday"),
        ("Sunday after [Monday]\u{2019} November 1, 2026", "Monday"),
        ("Sunday after {Monday}\u{2019} November 1, 2026", "Monday"),
        ("Sunday after on [Monday]! November 1, 2026", "Monday"),
        // The boundary: quoted words name verbatim,
        // exactly as R37-E pinned them — not residue,
        // unmoved.
        ("Sunday after \"Monday\" November 1, 2026", "\"Monday\""),
        (
            "Sunday after \u{201c}Monday\u{201d} November 1, 2026",
            "\u{201c}Monday\u{201d}",
        ),
        (
            "Sunday after \u{2018}Monday\u{2019} November 1, 2026",
            "\u{2018}Monday\u{2019}",
        ),
        (
            "Sunday after (\u{201c}Monday\u{201d}) November 1, 2026",
            "\u{201c}Monday\u{201d}",
        ),
        // The clean controls, at their standing
        // readings.
        ("Sunday after Monday November 1, 2026", "Monday"),
        ("Sunday after (Monday) November 1, 2026", "Monday"),
        ("Sunday after [Monday] November 1, 2026", "Monday"),
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: the disagreeing base refuses");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the mismatch is recorded");
        assert_eq!(m.named, named, "{line}: the record names the weekday");
        assert_eq!(m.date, nov(1), "{line}: the record names the base date");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: the keep route refuses too");
        let m = c
            .keep_through_weekday_mismatch
            .as_ref()
            .expect("the mismatch is recorded on the keep route");
        assert_eq!(m.named, named, "{line}: the keep record names the weekday");
        assert_eq!(
            m.date,
            nov(1),
            "{line}: the keep record names the base date"
        );
    }
    // The agreeing arm of a residue form: no record
    // stands and the phrase resolves, as it did.
    let line = "Sunday after [Sunday]! November 1, 2026";
    let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
    let c = parse_contribution(&text, today()).expect("parses");
    assert_eq!(
        c.for_date,
        Some(nov(8)),
        "{line}: the agreeing wrapped weekday lets the phrase resolve"
    );
    assert_eq!(c.named_weekday_mismatch, None, "{line}: no record stands");
}

#[test]
fn r37g_sunday_after_base_trailing_garnish_sequence_is_judged() {
    // Round 37 (R37-G, late batch on the R35-H
    // precedent; dispositioned by the coordinator
    // from the R37-D writer's witnessed flag,
    // recorded in r37d-record.md): the Sunday-after
    // base's trailing garnish escaped in compound
    // form. The lone garnish refuses with the
    // record against the BASE date — "Sunday after
    // November 1, 2026 (Monday)" records
    // WeekdayMismatch(Monday@2026-11-01) and serves
    // nothing — but "Sunday after November 1, 2026
    // (Monday)(notes)" and its mirror "(notes)
    // (Monday)" served 2026-11-08 silently on both
    // routes, because the base's trailing judgment
    // (`sunday_after_base` in dates.rs) asked only
    // for the line's last word, a third slot beside
    // the plain line's leading/trailing slots that
    // R37-D's walk covers. The base's judgment now
    // walks the group sequence standing after the
    // base date, as R37-D's walk does at the plain
    // slots: the first weekday group in written
    // order that disagrees with the base date
    // records the lone form's mismatch and refuses;
    // an agreeing sequence is consumed as the lone
    // agreeing garnish is. Every compound below
    // compares its FULL record against its
    // lone-garnish twin's (the r34e helpers), on
    // the For line and the Keep-through line; the
    // headline forms are stated outright after.
    // November 1, 2026 is a Sunday, so the Sunday
    // after it is November 8: "Monday" disagrees
    // with the base, "Sunday" agrees.
    let pair_shapes: [(&str, &str, &str, &str); 5] = [
        ("(", ")", "(", ")"),
        ("[", "]", "[", "]"),
        ("{", "}", "{", "}"),
        ("(", ")", "[", "]"),
        ("[", "]", "(", ")"),
    ];
    for (o1, c1, o2, c2) in pair_shapes {
        for word in ["Monday", "Sunday"] {
            let w = format!("{o1}{word}{c1}");
            let n = format!("{o2}notes{c2}");
            for compound in [
                format!("Sunday after November 1, 2026 {w}{n}"),
                format!("Sunday after November 1, 2026 {w} {n}"),
                format!("Sunday after November 1, 2026 {n}{w}"),
                format!("Sunday after November 1, 2026 {n} {w}"),
                format!("Sunday after November 1, 2026, {n}, {w}"),
                format!("Sunday after November 1, 2026 {w}, {n}"),
                format!("Sunday after November 1, 2026{w}{n}"),
            ] {
                let lone = format!("Sunday after November 1, 2026 {w}");
                r34e_for_twin(&compound, &lone);
                r34e_keep_twin(&compound, &lone);
            }
        }
    }
    // The mixed-pair wrapper and the doubled
    // wrapper as the weekday group, with a
    // companion beside them.
    for compound in [
        "Sunday after November 1, 2026 ([Monday])(notes)",
        "Sunday after November 1, 2026 (notes)([Monday])",
        "Sunday after November 1, 2026 ((Monday))((notes))",
        "Sunday after November 1, 2026 ((notes))((Monday))",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 ([Monday])");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 ([Monday])");
    }
    for compound in [
        "Sunday after November 1, 2026 ([Sunday])(notes)",
        "Sunday after November 1, 2026 (notes)([Sunday])",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 ([Sunday])");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 ([Sunday])");
    }
    // Three-group sequences: the weekday group
    // first, last, and in the middle — the walk is
    // over the sequence, not over a pair.
    for compound in [
        "Sunday after November 1, 2026 (Monday)(notes)(choir)",
        "Sunday after November 1, 2026 (notes)(choir)(Monday)",
        "Sunday after November 1, 2026 (notes)(Monday)(choir)",
        "Sunday after November 1, 2026 (Monday) (notes) (choir)",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 (Monday)");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 (Monday)");
    }
    // Two weekday groups in one sequence: the
    // first DISAGREEING weekday in written order
    // records, whichever position it stands in.
    for compound in [
        "Sunday after November 1, 2026 (Monday)(Sunday)",
        "Sunday after November 1, 2026 (Sunday)(Monday)",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 (Monday)");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 (Monday)");
    }
    // The base's own leading weekday agreed, and
    // the trailing sequence still speaks.
    r34e_for_twin(
        "Sunday after (Sunday) November 1, 2026 (Monday)(notes)",
        "Sunday after (Sunday) November 1, 2026 (Monday)",
    );
    r34e_keep_twin(
        "Sunday after (Sunday) November 1, 2026 (Monday)(notes)",
        "Sunday after (Sunday) November 1, 2026 (Monday)",
    );
    // Stated outright, the headline forms. A
    // disagreeing weekday group with a companion
    // after the base is refused with the lone
    // form's record, on both routes.
    for line in [
        "Sunday after November 1, 2026 (Monday)(notes)",
        "Sunday after November 1, 2026 (notes)(Monday)",
        "Sunday after November 1, 2026 (Monday) (notes)",
        "Sunday after November 1, 2026 [Monday][notes]",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date reads");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing weekday group with a companion is recorded");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: a weekday refusal carries no parenthesized record"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: no keep date reads");
        let m = c
            .keep_through_weekday_mismatch
            .as_ref()
            .expect("the disagreeing weekday group is recorded on the keep line");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
    }
    // The agreeing arm converges: an agreeing
    // weekday group with a companion after the
    // base is consumed exactly as the lone
    // agreeing garnish is — the Sunday after the
    // base reads clean, with no record, on both
    // routes.
    for line in [
        "Sunday after November 1, 2026 (Sunday)(notes)",
        "Sunday after November 1, 2026 (notes)(Sunday)",
        "Sunday after November 1, 2026 (Sunday) (notes)",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(8)), "{line}: the Sunday after reads");
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no record");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.keep_through,
            Some(nov(8)),
            "{line}: the keep Sunday after reads"
        );
        assert_eq!(c.keep_through_weekday_mismatch, None, "{line}: no record");
    }
}

#[test]
fn r37g_sunday_after_base_garnish_companions_keep_standing_judgments_and_boundaries_hold() {
    // Round 37 (R37-G), the companion side of the
    // base slot's walk and the boundaries it must
    // not cross. The walk judges the weekday
    // groups and nothing else: at this slot a
    // governing or date-carrying companion is
    // garnish with its own standing treatment —
    // standing alone after the base, "(cancelled)"
    // and "(November 8, 2026)" are each consumed
    // as garnish and the line resolves to
    // November 8 with no record of any kind — and
    // the walk neither adopts nor newly refuses
    // such a companion: beside a disagreeing
    // weekday group the weekday's refusal stands
    // exactly as the lone refusal does, and beside
    // an agreeing one the line reads as the lone
    // agreeing line reads.
    for compound in [
        "Sunday after November 1, 2026 (Monday)(cancelled)",
        "Sunday after November 1, 2026 (cancelled)(Monday)",
        "Sunday after November 1, 2026 (Monday)(November 8, 2026)",
        "Sunday after November 1, 2026 (November 8, 2026)(Monday)",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 (Monday)");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 (Monday)");
    }
    for compound in [
        "Sunday after November 1, 2026 (Sunday)(cancelled)",
        "Sunday after November 1, 2026 (cancelled)(Sunday)",
        "Sunday after November 1, 2026 (Sunday)(November 8, 2026)",
        "Sunday after November 1, 2026 (November 8, 2026)(Sunday)",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 (Sunday)");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 (Sunday)");
    }
    // The companions' standing garnish treatment
    // at this slot, stated outright: standing
    // alone after the base, each is consumed and
    // the Sunday after the base reads, with no
    // weekday record and no parenthesized record.
    for line in [
        "Sunday after November 1, 2026 (cancelled)",
        "Sunday after November 1, 2026 (November 8, 2026)",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(nov(8)), "{line}: the Sunday after reads");
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no weekday record");
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: no parenthesized record at this slot"
        );
    }
    // The curly trailing garnish arm fixed by
    // R37-E does not move: the bare curly-quoted
    // garnish is judged exactly as before, alone
    // and with a companion group after it.
    let text =
        "For Sunday: Sunday after November 1, 2026 \u{201c}Monday\u{201d}\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the curly garnish is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text = "For Sunday: Sunday after November 1, 2026 \u{201c}Monday\u{201d} (notes)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the curly garnish with a companion is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text =
        "For Sunday: Sunday after November 1, 2026 \u{201c}Sunday\u{201d}\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)));
    assert_eq!(c.named_weekday_mismatch, None);
    // The R5-D bare-word arm is untouched: words
    // standing after the garnish — after the lone
    // group or after a sequence — are the line's
    // remainder, and the garnish is not judged
    // across them, in either form.
    for line in [
        "Sunday after November 1, 2026 (Monday) notes",
        "Sunday after November 1, 2026 (Monday) for the picnic",
        "Sunday after November 1, 2026 (Monday)(notes) and more",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(
            c.for_date,
            Some(nov(8)),
            "{line}: the remainder form reads the Sunday after"
        );
        assert_eq!(
            c.named_weekday_mismatch, None,
            "{line}: the remainder form records nothing"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, Some(nov(8)), "{line}: the keep line reads");
        assert_eq!(c.keep_through_weekday_mismatch, None, "{line}: no record");
    }
    // The base's leading judgment is untouched: a
    // disagreeing leading weekday refuses whatever
    // the trailing sequence holds, and its record
    // is the one the line carries.
    let text = "For Sunday: Sunday after (Monday) November 1, 2026 (Sunday)(notes)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing leading weekday is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
}

#[test]
fn r38b_sequence_walks_take_the_lone_forms_sentence_separators() {
    // Round 38 (R38-B, F2 MAJOR = review R38-R1 +
    // red team RT38-4): the round-37 group-sequence
    // walks judged a narrower separator set than
    // the lone forms. The lone forms judge a weekday
    // group followed by sentence punctuation —
    // "(Monday); November 1, 2026",
    // "(Monday). November 1, 2026",
    // "(Monday): November 1, 2026",
    // "November 1, 2026 (Monday);", and
    // "Sunday after November 1, 2026 (Monday);" all
    // refuse with WeekdayMismatch(Monday@2026-11-01)
    // — but the walks admitted only whitespace and
    // comma separations, so one ";" "." or ":"
    // standing between the groups of a sequence, or
    // between the last leading group and its date,
    // handed the line back unjudged at every slot:
    // "(Monday); (notes) November 1, 2026",
    // "November 1, 2026 (notes); (Monday)", and
    // "Sunday after November 1, 2026 (Monday);
    // (notes)" all served silently on both routes.
    // The walks now take the lone forms' separator
    // set. Every compound below compares its FULL
    // record against its lone-group twin's (the
    // r34e helpers), on the For line and the
    // Keep-through line; the headline forms are
    // stated outright after. November 1, 2026 is a
    // Sunday: "Monday" disagrees, "Sunday" agrees,
    // and the Sunday after November 1 is
    // November 8.
    for sep in [';', '.', ':'] {
        // Leading: the separator between the groups
        // in either order, spaced and glued, between
        // the last group and the date, and through a
        // three-group sequence — the lone twin
        // carries the same separator after its one
        // group, the position the lone forms judge.
        for compound in [
            format!("(Monday){sep} (notes) November 1, 2026"),
            format!("(notes){sep} (Monday) November 1, 2026"),
            format!("(Monday){sep}(notes) November 1, 2026"),
            format!("(Monday)(notes){sep} November 1, 2026"),
            format!("(notes){sep} (Monday){sep} (choir) November 1, 2026"),
        ] {
            let lone = format!("(Monday){sep} November 1, 2026");
            r34e_for_twin(&compound, &lone);
            r34e_keep_twin(&compound, &lone);
        }
        // The framing garnish stack in front of the
        // leading sequence, with a separator inside
        // the sequence, as it stands in front of the
        // lone group wearing the same separator.
        let compound = format!("on (Monday){sep} (notes) November 1, 2026");
        let lone = format!("on (Monday){sep} November 1, 2026");
        r34e_for_twin(&compound, &lone);
        r34e_keep_twin(&compound, &lone);
        // Trailing: the separator between the groups
        // in either order, spaced and glued, and
        // through a three-group sequence.
        for compound in [
            format!("November 1, 2026 (notes){sep} (Monday)"),
            format!("November 1, 2026 (Monday){sep} (notes)"),
            format!("November 1, 2026 (notes){sep}(Monday)"),
            format!("November 1, 2026 (notes){sep} (Monday){sep} (choir)"),
        ] {
            r34e_for_twin(&compound, "November 1, 2026 (Monday)");
            r34e_keep_twin(&compound, "November 1, 2026 (Monday)");
        }
        // The Sunday-after base's trailing slot:
        // the separator between the groups in either
        // order, spaced and glued.
        for compound in [
            format!("Sunday after November 1, 2026 (Monday){sep} (notes)"),
            format!("Sunday after November 1, 2026 (notes){sep} (Monday)"),
            format!("Sunday after November 1, 2026 (notes){sep}(Monday)"),
        ] {
            r34e_for_twin(&compound, "Sunday after November 1, 2026 (Monday)");
            r34e_keep_twin(&compound, "Sunday after November 1, 2026 (Monday)");
        }
    }
    // The agreeing arm converges at every slot: an
    // agreeing weekday group in a separated
    // sequence is consumed exactly as the lone
    // agreeing group wearing the separator is.
    for (compound, lone) in [
        (
            "(Sunday); (notes) November 1, 2026",
            "(Sunday); November 1, 2026",
        ),
        (
            "(notes). (Sunday) November 1, 2026",
            "(Sunday). November 1, 2026",
        ),
        (
            "(Sunday)(notes): November 1, 2026",
            "(Sunday): November 1, 2026",
        ),
    ] {
        r34e_for_twin(compound, lone);
        r34e_keep_twin(compound, lone);
    }
    for compound in [
        "November 1, 2026 (notes); (Sunday)",
        "November 1, 2026 (Sunday). (notes)",
    ] {
        r34e_for_twin(compound, "November 1, 2026 (Sunday)");
        r34e_keep_twin(compound, "November 1, 2026 (Sunday)");
    }
    for compound in [
        "Sunday after November 1, 2026 (Sunday); (notes)",
        "Sunday after November 1, 2026 (notes): (Sunday)",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 (Sunday)");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 (Sunday)");
    }
    // Companion contents keep their standing
    // judgments beside a separator: the walk judges
    // the weekday group and nothing else, so a
    // date-carrying companion separated by ";"
    // stands exactly as its glued twin in the
    // r37d/r37g pin sets stands, and a governing
    // companion at the base-trailing slot stands
    // the same way. A governing companion at the
    // LEADING slot no longer stands with them: since
    // round 38 (R38-D, F4) its contents are judged
    // as the bare governor is judged, so the leading
    // arms below are pinned against their
    // governor-bared twins — RESTATED OUTRIGHT by
    // R38-D, flagged in the batch's writer note (the
    // pre-R38-D pins compared them to "(Monday)
    // November 1, 2026", encoding the wrapped
    // governor as garnish). Round 39 (R39-H, F10)
    // RESTATES the TRAILING arms the same way,
    // flagged in the batch record: a governing
    // companion at the trailing slot is now pinned
    // against its governor-bared twin; the
    // base-trailing arms below stand as they stood,
    // twin-compared to the lone weekday forms.
    for (compound, twin) in [
        (
            "(Monday); (cancelled) November 1, 2026",
            "(Monday); cancelled November 1, 2026",
        ),
        (
            "(Monday); (November 8, 2026) November 1, 2026",
            "(Monday) November 1, 2026",
        ),
    ] {
        r34e_for_twin(compound, twin);
        r34e_keep_twin(compound, twin);
    }
    // Round 40 (R40-E, F9) RESTATES the leading
    // governor-first separator arm of this pin
    // outright, flagged here and in the batch
    // record: the arm stood in the loop above as
    // the twin pair "(cancelled); (Monday)
    // November 1, 2026" / "cancelled; (Monday)
    // November 1, 2026", and on the audited tree
    // both dresses SERVED November 1 silently, for
    // the reason stated at the r37d restatement
    // above. Under adjudication 3 of the round-40
    // synthesis the separated company composes as
    // the glued company does: governed, with
    // WeekdayMismatch(Monday@2026-11-01) recorded,
    // in both dresses, stated outright here.
    r40e_governed_with_record("(cancelled); (Monday) November 1, 2026", "Monday", nov(1));
    r40e_governed_with_record("cancelled; (Monday) November 1, 2026", "Monday", nov(1));
    for (compound, twin) in [
        (
            "November 1, 2026 (Monday); (cancelled)",
            "November 1, 2026 (Monday); cancelled",
        ),
        (
            "November 1, 2026 (cancelled); (Monday)",
            "November 1, 2026 cancelled; (Monday)",
        ),
    ] {
        r34e_for_twin(compound, twin);
        r34e_keep_twin(compound, twin);
    }
    for compound in [
        "November 1, 2026 (Monday); (November 8, 2026)",
        "November 1, 2026 (November 8, 2026); (Monday)",
    ] {
        r34e_for_twin(compound, "November 1, 2026 (Monday)");
        r34e_keep_twin(compound, "November 1, 2026 (Monday)");
    }
    for compound in [
        "Sunday after November 1, 2026 (Monday); (cancelled)",
        "Sunday after November 1, 2026 (cancelled); (Monday)",
        "Sunday after November 1, 2026 (Monday); (November 8, 2026)",
        "Sunday after November 1, 2026 (November 8, 2026); (Monday)",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 (Monday)");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 (Monday)");
    }
    // Stated outright, the headline forms. A
    // disagreeing weekday group in a separated
    // sequence is refused with the lone form's
    // record, on both routes, at all three slots.
    for line in [
        "(Monday); (notes) November 1, 2026",
        "(Monday). (notes) November 1, 2026",
        "(notes): (Monday) November 1, 2026",
        "November 1, 2026 (notes); (Monday)",
        "November 1, 2026 (notes). (Monday)",
        "Sunday after November 1, 2026 (Monday); (notes)",
        "Sunday after November 1, 2026 (notes): (Monday)",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date reads");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing weekday group in a separated sequence is recorded");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: a weekday refusal carries no parenthesized record"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: no keep date reads");
        let m = c
            .keep_through_weekday_mismatch
            .as_ref()
            .expect("the disagreeing weekday group is recorded on the keep line");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
    }
    // The agreeing separated sequences serve clean,
    // stated outright at all three slots.
    for (line, served) in [
        ("(Sunday); (notes) November 1, 2026", nov(1)),
        ("November 1, 2026 (notes); (Sunday)", nov(1)),
        ("Sunday after November 1, 2026 (Sunday); (notes)", nov(8)),
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, Some(served), "{line}: the date reads");
        assert_eq!(c.named_weekday_mismatch, None, "{line}: no record");
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, Some(served), "{line}: the keep date reads");
        assert_eq!(c.keep_through_weekday_mismatch, None, "{line}: no record");
    }
    // Both slots carrying sequences at once, the
    // leading one separated: an agreeing leading
    // sequence leaves the trailing sequence to
    // speak, and a disagreeing leading sequence
    // speaks over an agreeing trailing one — the
    // trailing walk reads its date past the
    // separated leading run.
    let text =
        "For Sunday: (Sunday); (notes) November 1, 2026 (Monday)(notes)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing trailing sequence is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
    let text =
        "For Sunday: (Monday); (notes) November 1, 2026 (Sunday)(notes)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None);
    let m = c
        .named_weekday_mismatch
        .as_ref()
        .expect("the disagreeing leading sequence is recorded");
    assert_eq!(m.named, "Monday");
    assert_eq!(m.date, nov(1));
}

#[test]
fn r38b_sequence_suffix_peels_take_the_typographic_closing_quote() {
    // Round 38 (R38-B, F2, the suffix arm of review
    // R38-R1): the walks' suffix peels carried
    // U+201D but not U+2019, the typographic closing
    // single quote the lone readers' trim sets have
    // carried since R35-C/R37-E. The lone forms
    // wearing it refuse — "November 1, 2026
    // (Monday)\u{2019}" and "Sunday after
    // November 1, 2026 (Monday)\u{2019}" both record
    // WeekdayMismatch(Monday@2026-11-01) — but a
    // sequence wearing it served silently:
    // "November 1, 2026 (Monday)(notes)\u{2019}" and
    // its base-trailing twin. U+2019 now joins
    // every suffix peel the walks state, at both
    // trailing walks and at the leading walk's own
    // suffix position (between the last group and
    // the date, where the lone leading form wearing
    // it, "(Monday)\u{2019} November 1, 2026", is
    // judged), and it stands in a sequence's gaps
    // as the preceding group's suffix. Every form
    // below compares its FULL record against its
    // lone twin's (the r34e helpers), on both
    // routes; the headline forms are stated
    // outright after. November 1, 2026 is a Sunday.
    // The trailing walks' suffix forms, U+2019
    // beside the standing controls the witnesses
    // held (U+201D, the straight quotes, "!", ".").
    for mark in ['\u{2019}', '\u{201d}', '\'', '"', '!', '.'] {
        let compound = format!("November 1, 2026 (Monday)(notes){mark}");
        let lone = format!("November 1, 2026 (Monday){mark}");
        r34e_for_twin(&compound, &lone);
        r34e_keep_twin(&compound, &lone);
        let compound = format!("Sunday after November 1, 2026 (Monday)(notes){mark}");
        let lone = format!("Sunday after November 1, 2026 (Monday){mark}");
        r34e_for_twin(&compound, &lone);
        r34e_keep_twin(&compound, &lone);
    }
    // U+2019 standing as a group's suffix inside
    // the sequence, at all three slots, in either
    // order, and at the leading walk's tail.
    for compound in [
        "November 1, 2026 (Monday)\u{2019} (notes)",
        "November 1, 2026 (notes)\u{2019} (Monday)",
    ] {
        r34e_for_twin(compound, "November 1, 2026 (Monday)\u{2019}");
        r34e_keep_twin(compound, "November 1, 2026 (Monday)\u{2019}");
    }
    for compound in [
        "Sunday after November 1, 2026 (Monday)\u{2019} (notes)",
        "Sunday after November 1, 2026 (notes)\u{2019} (Monday)",
    ] {
        r34e_for_twin(compound, "Sunday after November 1, 2026 (Monday)\u{2019}");
        r34e_keep_twin(compound, "Sunday after November 1, 2026 (Monday)\u{2019}");
    }
    for compound in [
        "(Monday)\u{2019} (notes) November 1, 2026",
        "(notes)\u{2019} (Monday) November 1, 2026",
        "(Monday)(notes)\u{2019} November 1, 2026",
    ] {
        r34e_for_twin(compound, "(Monday)\u{2019} November 1, 2026");
        r34e_keep_twin(compound, "(Monday)\u{2019} November 1, 2026");
    }
    // The agreeing arm converges: an agreeing
    // sequence wearing U+2019 is consumed exactly
    // as the lone agreeing group wearing it is, at
    // all three slots.
    r34e_for_twin(
        "November 1, 2026 (Sunday)(notes)\u{2019}",
        "November 1, 2026 (Sunday)\u{2019}",
    );
    r34e_keep_twin(
        "November 1, 2026 (Sunday)(notes)\u{2019}",
        "November 1, 2026 (Sunday)\u{2019}",
    );
    r34e_for_twin(
        "Sunday after November 1, 2026 (Sunday)(notes)\u{2019}",
        "Sunday after November 1, 2026 (Sunday)\u{2019}",
    );
    r34e_keep_twin(
        "Sunday after November 1, 2026 (Sunday)(notes)\u{2019}",
        "Sunday after November 1, 2026 (Sunday)\u{2019}",
    );
    r34e_for_twin(
        "(Sunday)(notes)\u{2019} November 1, 2026",
        "(Sunday)\u{2019} November 1, 2026",
    );
    r34e_keep_twin(
        "(Sunday)(notes)\u{2019} November 1, 2026",
        "(Sunday)\u{2019} November 1, 2026",
    );
    // Stated outright, the headline forms. A
    // disagreeing sequence wearing U+2019 is
    // refused with the lone form's record, on both
    // routes, at all three slots.
    for line in [
        "November 1, 2026 (Monday)(notes)\u{2019}",
        "Sunday after November 1, 2026 (Monday)(notes)\u{2019}",
        "(Monday)(notes)\u{2019} November 1, 2026",
    ] {
        let text = format!("For Sunday: {line}\n\n## Announcement\n\nHi.\n");
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.for_date, None, "{line}: no date reads");
        let m = c
            .named_weekday_mismatch
            .as_ref()
            .expect("the disagreeing sequence wearing U+2019 is recorded");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
        assert_eq!(
            c.for_sunday_parenthesized_mismatch, None,
            "{line}: a weekday refusal carries no parenthesized record"
        );
        let text = format!(
            "For Sunday: November 1, 2026\nKeep-through: {line}\n\n## Announcement\n\nHi.\n"
        );
        let c = parse_contribution(&text, today()).expect("parses");
        assert_eq!(c.keep_through, None, "{line}: no keep date reads");
        let m = c
            .keep_through_weekday_mismatch
            .as_ref()
            .expect("the disagreeing sequence is recorded on the keep line");
        assert_eq!(m.named, "Monday", "{line}");
        assert_eq!(m.date, nov(1), "{line}");
    }
}

// Round 38 (R38-C, F3 MAJOR = red team RT38-2): the
// R36-D / R37-B group judgment
// (`group_beside_relative_core`) was consulted at the
// leading slot and at the non-leading pre-phrase slot,
// but not at two further positions where the plain
// reading adopts a bracket/brace group's date as a
// plain framed signal while the paren twin reads
// nothing: between a Sunday-after phrase's own words
// ("Sunday [November 8, 2026] after November 1, 2026"
// served November 8 with the base demoted to a
// second-date note; the disagreeing form adopted
// November 15; the base-restating form adopted
// November 1), and after a weekday word before a
// relative phrase ("Sunday [November 8, 2026] next
// Sunday" adopted November 8). The judgment is now
// consulted at those interior positions as at the
// non-leading pre-phrase slot, in the same one place:
// the bracket/brace group there takes the paren
// reading — silence, the phrase's own reading
// governing — and is never adopted. Every pin below
// asserts the bracket/brace line's FULL record equals
// its paren twin's (the r34e helpers), on both routes
// (For / Keep-through), with the headline forms stated
// outright. The pins run at the suite's today,
// 2026-10-16, so "next Sunday" resolves October 25,
// "this Sunday" October 18, the Sunday after next
// Sunday November 1, and the Sunday after
// November 1, 2026 is November 8.

#[test]
fn r38c_split_sunday_after_group_takes_the_paren_reading_in_every_pair() {
    // The split-phrase family: a date group standing
    // between the phrase's "Sunday" and its "after" —
    // naming the resolution (November 8), another
    // Sunday (November 15), and the base itself
    // (November 1, the restating form) — plus the
    // short form, doubled wrappers, the phrase's own
    // framing stack ("the Sunday" / "on Sunday"), and
    // ordinary lead-in words before the phrase, which
    // the Sunday-after reader itself walks past.
    for (wrapped, paren) in [
        (
            "Sunday [November 8, 2026] after November 1, 2026",
            "Sunday (November 8, 2026) after November 1, 2026",
        ),
        (
            "Sunday {November 8, 2026} after November 1, 2026",
            "Sunday (November 8, 2026) after November 1, 2026",
        ),
        (
            "Sunday [November 15, 2026] after November 1, 2026",
            "Sunday (November 15, 2026) after November 1, 2026",
        ),
        (
            "Sunday {November 15, 2026} after November 1, 2026",
            "Sunday (November 15, 2026) after November 1, 2026",
        ),
        (
            "Sunday [November 1, 2026] after November 1, 2026",
            "Sunday (November 1, 2026) after November 1, 2026",
        ),
        (
            "Sunday {November 1, 2026} after November 1, 2026",
            "Sunday (November 1, 2026) after November 1, 2026",
        ),
        (
            "Sunday [November 8] after November 1, 2026",
            "Sunday (November 8) after November 1, 2026",
        ),
        (
            "Sunday {November 8} after November 1, 2026",
            "Sunday (November 8) after November 1, 2026",
        ),
        (
            "Sunday [[November 8, 2026]] after November 1, 2026",
            "Sunday ((November 8, 2026)) after November 1, 2026",
        ),
        (
            "Sunday {{November 8, 2026}} after November 1, 2026",
            "Sunday ((November 8, 2026)) after November 1, 2026",
        ),
        (
            "the Sunday [November 8, 2026] after November 1, 2026",
            "the Sunday (November 8, 2026) after November 1, 2026",
        ),
        (
            "the Sunday {November 8, 2026} after November 1, 2026",
            "the Sunday (November 8, 2026) after November 1, 2026",
        ),
        (
            "on Sunday [November 8, 2026] after November 1, 2026",
            "on Sunday (November 8, 2026) after November 1, 2026",
        ),
        (
            "choir Sunday [November 8, 2026] after November 1, 2026",
            "choir Sunday (November 8, 2026) after November 1, 2026",
        ),
        (
            "notes Sunday {November 8, 2026} after November 1, 2026",
            "notes Sunday (November 8, 2026) after November 1, 2026",
        ),
        (
            "words for Sunday [November 8, 2026] after November 1, 2026",
            "words for Sunday (November 8, 2026) after November 1, 2026",
        ),
    ] {
        r34e_for_twin(wrapped, paren);
        r34e_keep_twin(wrapped, paren);
    }
    // Stacked groups at the split position, agreeing,
    // disagreeing, and mixed pairs: the paren stacks
    // are silent, so no stacked-agreeing adoption
    // stands at this slot (the R37-B exception belongs
    // to the pre-phrase slot, where the stacks adopt
    // in the paren form's own mixed pairs).
    for (wrapped, paren) in [
        (
            "Sunday [November 8, 2026] [November 8, 2026] after November 1, 2026",
            "Sunday (November 8, 2026) (November 8, 2026) after November 1, 2026",
        ),
        (
            "Sunday [November 8, 2026] [November 15, 2026] after November 1, 2026",
            "Sunday (November 8, 2026) (November 15, 2026) after November 1, 2026",
        ),
        (
            "Sunday [November 8, 2026] (November 15, 2026) after November 1, 2026",
            "Sunday (November 8, 2026) (November 15, 2026) after November 1, 2026",
        ),
        (
            "Sunday (November 8, 2026) [November 15, 2026] after November 1, 2026",
            "Sunday (November 8, 2026) (November 15, 2026) after November 1, 2026",
        ),
    ] {
        r34e_for_twin(wrapped, paren);
        r34e_keep_twin(wrapped, paren);
    }
    // A trailing weekday garnish after the base, and
    // a trailing group after the phrase: the garnish
    // forms take the paren silence, and beside a
    // trailing group the For route is silent while
    // the Keep-through line stands the trailing
    // group, in every pair.
    for (wrapped, paren) in [
        (
            "Sunday [November 8, 2026] after November 1, 2026 Monday",
            "Sunday (November 8, 2026) after November 1, 2026 Monday",
        ),
        (
            "Sunday [November 8, 2026] after November 1, 2026 Sunday",
            "Sunday (November 8, 2026) after November 1, 2026 Sunday",
        ),
        (
            "Sunday [November 8, 2026] after November 1, 2026 (November 15, 2026)",
            "Sunday (November 8, 2026) after November 1, 2026 (November 15, 2026)",
        ),
        (
            "Sunday {November 8, 2026} after November 1, 2026 (November 15, 2026)",
            "Sunday (November 8, 2026) after November 1, 2026 (November 15, 2026)",
        ),
    ] {
        r34e_for_twin(wrapped, paren);
        r34e_keep_twin(wrapped, paren);
    }
    // The paren reading stated outright: total
    // silence on the For route — no date, no memory,
    // no parenthesized date, no second date — and
    // the Keep-through line keeps nothing.
    let text =
        "For Sunday: Sunday (November 8, 2026) after November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, None, "the split line reads no date");
    assert_eq!(c.for_sunday_in_words, None, "and remembers nothing");
    assert_eq!(
        c.for_sunday_after_in_words, None,
        "and remembers nothing in after-words"
    );
    assert_eq!(
        c.for_sunday_parenthesized_date, None,
        "and surfaces no parenthesized date"
    );
    assert_eq!(
        c.for_sunday_second_dates,
        Vec::<SimpleDate>::new(),
        "and names no second date"
    );
    let text = "For Sunday: November 1, 2026\nKeep-through: Sunday (November 8, 2026) after November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.keep_through, None, "the split keep line keeps nothing");
    assert_eq!(
        c.keep_through_second_dates,
        Vec::<SimpleDate>::new(),
        "with no second date from the base"
    );
    // Beside a trailing group the keep-through line
    // stands the trailing group, stated outright.
    let text = "For Sunday: November 1, 2026\nKeep-through: Sunday (November 8, 2026) after November 1, 2026 (November 15, 2026)\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(
        c.keep_through,
        Some(nov(15)),
        "the keep line stands the trailing group"
    );
    // The clean phrase is unmoved: it resolves
    // November 8 on both routes.
    let text = "For Sunday: Sunday after November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(c.for_date, Some(nov(8)), "the clean phrase resolves");
    let text = "For Sunday: November 1, 2026\nKeep-through: Sunday after November 1, 2026\n\n## Announcement\n\nHi.\n";
    let c = parse_contribution(text, today()).expect("parses");
    assert_eq!(
        c.keep_through,
        Some(nov(8)),
        "the clean keep phrase resolves"
    );
}

